(window.STORIES=window.STORIES||[]).push(...[{"n": 114, "l": "الجزء 88 | احداث السنه الرابعه من الهجره | موقف رسول الله صلى الله عليه وسلم من الاطفال | غذوة بدر الصغري", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثامنة_والثمانون\n#أحداث_السنة_الرابعة_من_الهجرة\n#موقف_رسول_الله_من_الأطفال\n#غزوة_بدر_الصغرى\nاتكلمنا المرة إللي فاتت عن الأحداث في بداية السنة الرابعة من الهجرة واتكلمنا عن موت أبي سلمة رضي الله عنه في شهر جمادى الأولى،\nوفي نفس الشهر مات حفيد رسول الله ﷺ، عبد الله بن عثمان بن عفان وكان عمره ست سنوات، أمه رقية بنت رسول الله ﷺ إللي كانت مريضة وماتت بعد غزوة بدر سنة اثنين هجريا،\nوفي السنة الرابعة من الهجرة خطب رسول الله ﷺ زينب بنت جحش ابنة عمته لمولاه زيد بن الحارثة إللي كان اسمه زيد بن محمد لحد اللحظة دي،\nفلما خطبها فكرت إنه خطبها لنفسه فوافقت، لكن لما عرفت إنه خطبها لمولاه زيد رفضت، إزاي يزوّجها لمولى، يعني عبد سابق وهي كانت ذات شرف وحسب،\nيعني هي كانت من طبقة راقية وهو لأ، فنزل القرآن يقول:\n\"وَمَا كَانَ لِمُؤْمِنٍ وَلا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُ أَمْرًا أَنْ يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ فَقَدْ ضَلَّ ضَلالا مُبِينًا\"\nيعني مادام رسول الله ﷺ خلاص أمر يبقى يجب الطاعة\nفوافقت زينب رضي الله عنها إنها تتزوج من زيد طاعة لأمر رسول الله ﷺ وتم الزواج بين زيد وزينب بنت جحش رضي الله عنهم أجمعين.\n☆ممكن حد يقول طيب ده زواج، يعني إزاي رسول الله ﷺ يأمرها بحاجة هي مش عايزاها\nشوفوا يا جماعة الموضوع له حكمة، \nلكن الحكمة دي مش هتظهر دلوقتي هتظهر بعدين، بعد حوالي سنة تقريبا،\nفالاختبار في الإيمان هنا إن المسلم ينفذ أمر رسول الله ﷺ ولو كان مخالف لهواه ورغباته، \nماهو الواحد لو عرف الحكمة من كل حاجة قبل ما ينفذ الأمر أكيد هينفذه وهو راضي،\nوبكده هيدخل صادق الإيمان مع غير الصادق\nبعكس إللي يجيله الأمر من رسول الله ﷺ وهو مخالف لهواه ورغباته،\nلو هو فعلا صادق الإيمان هنلاقيه نفذ على طول،\nزي زينب رضي الله عنها في الموقف ده، تخيلوا وافقت على الزواج وإنها تعيش مع رجل مش عايزاه لمجرد إن رسول الله ﷺ أمرها بكده، \nوالموضوع مش سهل خالص على فكرة\nواحنا قلنا قبل كده إن رسول الله ﷺ قال :\n\"لا يُؤمن أحدكم حتى يكون هواهُ تبعًا لما جئتُ به\"\nفأمر رسول الله ﷺ هنا أمر تشريعي،\nيعني بيقول للمسلمين بطريقة عملية إن الأصل في الزواج بيكون على حسب الخلق والدين، وإن اختلاف الطبقات بين الرجل والمرأة مش سبب رئيسي يمنع الزواج بينهم زي ما كان مشهور أيام الجاهلية،\nفالإسلام جاء عشان يزيل الفروق الطبقية دي، وإن مفيش تفاخر بين الناس ولا في فرق بينهم إلا بالتقوى،\nفتخيلوا لما زينب أطاعت أمر رسول الله ﷺ وتنازلت عن نزعة الحسب والشرف ربنا هيعوضها بعدين بشرف أعظم تتفاخر بيه بين نساء رسول الله ﷺ لما تتزوجه ﷺ، وهنحكي عن الموضوع بالتفصيل لما ييجي وقتها إن شاء الله، كل ده لأنها أطاعت أمر الله وأمر رسوله \nوعلى فكرة هي مكنتش مستنية إن ربنا يعوضها ولا اشترطت على رسول الله ﷺ بشيء، ولا منّت عليه،\nيعني مقلتش يا رسول أنا هتزوجه واسمع كلامك بس يكون في مقابل لموافقتي دي، ده أنا هضحي وأتزوج عشان خاطرك زي ما بنشوف الكلام ده دلوقتي في زماننا، \nولا كانت تعرف الكرامات إللي ربنا هيرزقها بيها،\nجالها الأمر فسمعت الكلام ونفذت فورا إرضاءا لله ورسوله ولأن ربنا عالم باللي في قلبها، وبصدق اتباعها لله ولرسوله كانت مكافئتها من عند ربنا عظيمة\nومن هنا نتعلم إننا لما نطيع أمر الله ورسوله بنطيع لمجرد إن ربنا أمر، أما الجزاء فاحنا مستنيينه في الآخرة، من غير بقى ما نقعد نتشرّط ونبقى مستنيين العوض في الدنيا، \nولو العوض ده مجاش نقعد نتسخّط ونَمُن على ربنا، يارب أنا سمعت كلامك وسيبت الغلط عشانك، فين بقى تعويضك لي\nسواء ربنا عوضنا في الدنيا أو لأ فاحنا بنطيع أوامره لأننا عايزين أجر الآخرة، لأن هو ده الجزاء الدائم،\nأنا بقول الكلام ده يا جماعة عشان ساعات ربنا لحكمة يعلمها يأخر عننا العوض في الدنيا فيبدأ الشيطان يشككنا في الجزاء بتاع ربنا،\n فخلونا دايما ننظر لجزاء الآخرة لأن هو ده الجزاء الباقي للأبد، ومتخلوش تأخر الجزاء في الدنيا سبب لترك طاعة الله ورسوله\nيبقى زيد بن حارثة رضي الله عنه أو خلونا نقول اسمه المعروف به لحد دلوقتي زيد بن محمد تزوج من زينب بنت جحش، خليكم فاكرين الحدث ده عشان بعد سنة تقريبا هتحصل أحداث كبيرة في المدينة\nالأحداث اليومية لرسول الله ﷺ مع الصحابة مستمرة، بيصلي معاهم الصلوات...بيجاوب على أسألتهم...\nبيلاعب صبيانهم، \nوكان له ﷺ مواقف جميلة مع الأطفال منها:\nإنه كان بيرش وجه الواحد منهم بالمية ويضحك \nوكان بيهزر مع واحد تاني ويقول له: \"يا ذا الأذنين\" ، كإنها حاجة غريبة وهي حاجة عادية أصلا، لأن كل واحد عنده أذنين فكانوا فبيضحكوا كلهم\nوكان بيحب يفرّحهم باللعب المفيد معاهم، فكان بيوقّف بعض الأطفال صفوف ويقول لهم: \nتسابقوا وإللي يوصل لي الأول له مكافأة كذا وكذا!\nفيستبقون إليه، فيقعون على ظهره وصدره، ويتمرغون فيه  فيقبّلهم ويحضنهم ﷺ \nعشان كده الأطفال كانوا بيحبوه جدا، وده يفسّر ليه الصبيان أول ما عمرو بن أمية الضّمري وصل للمدينة الصبيان جريوا على رسول الله ﷺ عشان يقولوا له على مجيء عمرو،\nمكنش في أي حاجز بين رسول الله ﷺ وبين رعيّته سواء الكبير أو الصغير...الحر أو العبد\nشوفتوا إزاي على الرغم من إن رسول الله ﷺ أصلا مش فاضي ووراه مسؤوليات الجهاد واحنا داخلين أصلا على معركة مع قريش على حسب الاتفاق، فالمفروض إنه دلوقتي بيجهز للمعركة دي ومش فاضي، ومع ذلك كان بيلعب مع الأطفال\n☆أظن ملناش عذر بعد كده إننا نسيب عيالنا من غير ما نلعب ولا نهزر معاهم\nمحدش فينا كان مشغول زي رسول الله ﷺ سواء أباء أو أمهات، \nلو اقتطعنا بس ربع ساعة كل يوم نلعب معاهم فيها بأي لعبة بيحبوها مادام مُباحة ونضحك معاهم فيها بعيد عن كل المشاكل؛ هتفرق جدا في نفسيتهم ونفسيتنا احنا قبلهم،\nده حتى ضحكات الأطفال أصلا جميلة وبتنشر البهجة وتفرح القلب الحزين\nضحَّكوا أولادكم وفرّحوهم، هم كمان محتاجين هزاركم مش أصحابكم بس\nوعلى الفكرة الضحك والهزار ده مش بيقلل الوقار ولا الاحترام \nإلا طبعا لو كان بِسَفه وتعدّي وإلغاء لحدود الأدب والاحترام \nحاولوا ميعديش عليكم يوم من غير ما تهزروا مع أولادكم وتخرجوا الضحكة من قلوبهم، وخلوا نيتكم:\n♡إدخال السرور على قلب مسلم صغير بريء يحبه الله.\n♡إننا نقتدي برسول الله ﷺ، لأن الهدف من معرفة السيرة أصلا إننا نعرف حياته ﷺ ونقلده في كل شيء\n♡تقوية العلاقة بين أفراد الأسرة.\n♡نعرّفهم أد إيه الإسلام فعلا جميل وبيراعي حقوقهم وحريص على إنه يفرحهم، وإنه مش مجرد أوامر ونواهي وخلاص\nالشباب إللي بيلحد ده لو كان عرف الإسلام الصحيح المتكامل مكنش ألحد ولا كان اتكلم عن الإسلام بالطريقة دي\nطبعا مش هوصيكم \nالهزار ميكونش بالشتيمة ولا بالكذب ولا بشيء مؤذي ولا بإنكم تخبوا حاجاتهم عشان تخوّفوهم وبعدين تضحكوا عليهم، \nوميكونش الهزار بالاستهزاء بشيء من الدين، ولا فيه غيبة أو نميمة أو سخرية، نهزر معاهم الهزار المباح زي هزار رسول الله ﷺ\nدخلنا في شهر شعبان وفي بداية الشهر في اليوم الثالث منه وُلد الحسين بن علي رضي الله عنه ابن فاطمة الزهراء ابنة رسول الله ﷺ،\nوكان رسول الله ﷺ هو من سماه الحسين،\nرسول الله ﷺ كان بيعطي كل حاجة حقها، مكنش بيخلي حاجة تطغى على حاجة، \nيعني مكنش بيخلي حزنه يمنعه عن إنه يساعد الصحابة وينصحهم ويشوف مشاكلهم وإنه يقوم بواجباته تجاه أهل بيته،\nولا كان بيخلي فرحه يمنعه عن الجهاد والتجهيز للمعارك مثلا،\nكل حاجة لها وقتها\nيعني هو كان فرحان بمولد الحسين رضي الله عنه وانتم عارفين الأجداد بيحبوا أحفاهم أد إيه، \nوفي نفس الوقت كان بيجهز الجيش ويجمع المسلمين للقاء المشركين؛ لأن الاتفاق بعد غزوة أحد كان إن المشركين السنة الجاية هيتقابلوا مع المسلمين في حرب تانية عشان يحددوا المنتصر منهم،\nغزوة أحد كانت في شوال من السنة الثالثة من الهجرة، والميعاد إللي اتفق عليه المشركون والمسلمون المفروض إنه في شوال من السنة الرابعة من الهجرة عند ماء بدر،\nرسول الله ﷺ جهز جيشه وأرسل رسالة لقريش في شهر شعبان بيأكّد عليهم الميعاد يعني بعد سنة تقريبا من غزوة أُحد، وخرج رسول الله ﷺ لبدر في جيش عدده ألف وخمسمائة مقاتل،\nوجهز أبو سفيان جيش هو كمان وخرج بألفين مقاتل، ووصل أبو سفيان لمنطقة قريبة جدا من مكة اسمها مَر الظّهران وعسكر هناك،\nولسه قصاده مشوار طويييل لبدر\nجيش المشركين إللي خرج ده خرج بالعافية، هم مش عايزين يواجهوا المسلمين تاني وخايفين منهم ومترددين في الخروج،\nفأبو سفيان وقف وقال لهم:\nيا معشر قريش! السنة دي سنة جدْب وقحط، ومش هينفع نخرج إلا في عام خِصب ترعون فيه الشجر وتشربون فيه اللبن، وأنا هرجع فارجعوا\nيعني بيقول لهم الزرع قليل أوي السنة دي، ومش هينفع معانا غير عام خصب الزرع فيه كثير ،عشان البعير ياكل كويس ويخرج لبن كثير وتشربوه وتتقوُّوا به عالحرب،\nإللي هو أي حجج وخلاص عشان يهربوا من مواجهة المسلمين\nتخيلوا بقى إن مفيش ولا واحد عارض قرار أبو سفيان وفعلا رجعوا كلهم\nما هم لو كانوا حريصين على قتال رسول الله ﷺ والمسلمين كانوا جهزوا وجمّعوا فعلا وخرجوا للقتال زي ما خرجوا في غزوة بدر وأحد،\nواحنا شفنا حماسهم وإصرارهم وتجهيزهم كان عامل إزاي في بدر وأحد،\nفكان واضح جدا إنهم مش عايزين يقابلوا المسلمين في معركة،\nرسول الله ﷺ قاعد مستنيهم، وكان من عادته إنه يفضل قاعد في مكان المعركة بعد انتصاره ثلاثة أيام،\nدلوقتي قريش رجعت ورسول الله ﷺ مستني، فانسحاب المشركين معناه نصر المسلمين، \nرسول الله ﷺ مقعدش بقى ثلاثة أيام زي كل مرة، لأ ده قعد ثمانية أيام متصلة في بدر\nإللي هو بيعلن لكل الناس:\nشوفتم أنا قاعد مستني جيش مكة ومش خايف لا من قوتهم ولا أسلحتهم وهمّ إللي خافوا مننا احنا المسلمين ورجعوا لمكة\nوالموضوع ده كان له أثر كبير جدا في كل الجزيرة العربية؛\nلأن جيش مكة هو أقوى قوة في الجزيرة وأكثر الجيوش تنظيم، \nفلما جيش زي ده ينسحب من أمام المسلمين بعد ما كانوا هم إللي طلبوا الحرب دي؛ أكيد طبعا ده في مصلحة الإسلام والمسلمين، وزاد من تثبيت أركان دولة الإسلام في الجزيرة،\nوالقبائل بدأت تخاف من قوة المسلمين،\nوحتى كثير من الأعراب حول المدينة عملوا صلح مع رسول الله ﷺ\nرجع رسول الله ﷺ للمدينة وطبعا المسلمين فرحانين بالنصر إللي جاء لهم هدية من عند ربنا\nدخل شهر رمضان وصام المسلمون وصلوا وتحروا ليلة القدر وأخرجوا زكاة الفطر وجاء شهر شوال،\nفي شهر شوال انقضت عدة أم سلمة رضي الله عنها ، وعدة المُتوَفى عنها زوجها أربعة أشهر وعشرة أيام،\nأما لو كانت حامل فعدتها بتخلص أول ما تولد\nبعد انتهاء عدتها تقدم لخطبتها أبو بكر فرفضت، وتقدم لخطبتها عمر بن الخطاب فرفضت.\n☆والعِدة معناها : الأيام إللي المرأة تنحبس فيها عن الزواج، يعني بعد موت زوج المرأة أو طلاقها أو خُلعها تقعد أيام معينة قبل ما تتزوج مرة ثانية.\nأم سلمة رضي الله عنها اسمها الحقيقي هند بنت أبي أمية من قبيلة بني مخزوم، وهي ابنة عم خالد بن الوليد،\nوكان عمرها بعد انقضاء العِدة حوالي سبعة وعشرين سنة وعندها أربعة أطفال وكانت من أجمل النساء،\nفأرسل رسول الله ﷺ لها من يخطبها، لكنها ردت على رسول الله ﷺ بأنها امرأة شديدة الغيرة، يعني هتغير من زوجات رسول الله ﷺ وكمان عندها أطفال ومفيش حد من أوليائها حاضر،\nفجاءها رسول الله ﷺ بنفسه وقال لها:\nأما غَيرتك، فسأدعو الله أن يُذهبها، وأطفالك على الله ورسوله، يقصد إنه هيُراعيهم معاها،\nومفيش أي أحد من أوليائك يكره إني أتزوجك، فوافقت أم سلمة وتزوجت برسول الله ﷺ،\nوعاشت في بيت زينب بنت خزيمة رضي الله عنها بعد موتها، وكان عندها طفلة رضيعة اسمها زينب، كان كل ما رسول الله ﷺ يدخل على أم سلمة يسأل عنها ويقول:\nأين زُناب؟\nبيدلّع زينب يعني، وكان بيتلطف مع أولاد أم سلمة ﷺ\nوالسيدة أم سلمة أكثر زوجات رسول الله ﷺ رواية للحديث بعد السيدة عائشة رضي الله عنهما، وكانت امرأة عاقلة حكيمة.\nلما السيدة عائشة عرفت إن رسول الله ﷺ تزوج أم سلمة حزنت جدا لما حكوا لها عن جمال أم سلمة رضي الله عنها فلما شافتها السيدة عائشة قالت إن جمالها كان أضعاف الوصف إللي اتوصف لها،\nفحكت لحفصة وكانوا أصحاب، فقالت لها حفصة:\nلا والله، إنْ هذه إلا الغيرة، ماهي كما تقولين وإنها لجميلة\nيعني السيدة حفصة بتقول لها أيوة هي جميلة لكن مش زي مانتي متصورة، دي الغيرة إللي خلتك تشوفيها بالجمال الزيادة ده،\nفقالت السيدة عائشة : \nفرأيتها بعدُ، فكانت كما قالت حفصة ولكني كنت غَيْرى.\nيعني بتقول إنها شافت أم سلمة بعد كده وفعلا كانت زي ما حفصة قالت، لكنها كانت بتغير.\n☆الغيرة يا جماعة طبع في البشر، وطبيعي جدا إن المرأة تغير على زوجها من النساء، لكن الغيرة إللي تؤدي لمعصية الله هي غيرة مذمومة،\nيعني مينفعش عشان واحدة بتغير على زوجها تقوم تتعدى حدودها وتقعد تتجسس عليه وتفتش وراه وفي حاجته سواء الهاتف بتاعه أو أي حاجة تخصه لمجرد إنها بتغير عليه وبتظن فيه ظن سوء وخايفة يعمل حاجة من وراها،\nالتجسس حرام شرعا ومفيش أي مُبرر يعطي الحق للزوج أو الزوجة إنهم يتجسسوا على بعض، \nوالناس إللي بتغير زيادة عن اللزوم وشكاكة بتعيش في تعاسة وبتعاني فعلا\nوالغيرة لها حل ومن أهم الحلول الدعاء زي ما رسول الله ﷺ قال لأم سلمة ندعو الله فيذهب الغيرة من قلبك،\nيعني الدعاء لأم سلمة مكنش حاجة خاصة برسول الله ﷺ ولا خاصة بأم سلمة لوحدها، ده هو ﷺ بيقدم حل عملي لكل امرأة غيور،\nبتغِيري والغيرة مجنناكِ ادعي ربنا 《بصدق》 يشيل الغيرة من قلبك، ماهي القلوب دي بين إيدين ربنا وهو القادر على تحويلها في أي لحظة،\nوعلى فكرة مش شرط بس الغيرة على الأزواج ، حتى الغيرة بين الإخوات وبعضهم، والغيرة بين الأصحاب والغيرة بين الأقارب وحتى الغيرة بين طلبة العلم تخيلوا\nبالدعاء ربنا قادر إنه ينزع الغيرة دي من القلوب،\nطبعا بنتكلم عن الغيرة الزايدة عن حدها إللي ممكن تؤدي إلى معصية الله\nومن الأمور إللي بتساعد إن الغيرة تبقى محمودة وفي حدود الشرع: \nتقوى الله، وإن الإنسان لا يُقارِن نفسه بغيره، ويشغل وقته بالأمور النافعة،\nلأن الفراغ بيفتح باب للتفكير السلبي ووساوس الشيطان،\nوطبعا الإنسان يبعد عن الناس إللي بتقعد تثير الغيرة وتسخّن الدنيا\nولازم إحسان الظن وعدم التجسس والإنسان يكون عنده ثقة بنفسه\nلو لاحظتم وركزتم كويس هتلاقوا معظم الناس إللي عندهم غيرة مُفرطة إن مكنش كلهم مش بيعملوا الحاجات إللي قلت عليها دي، \nيعني نقطة واحدة بس كافية إن الغيرة تبقى زايدة عن حدها ويحصل بسببها كوارث ،فتخيلوا بقى لما كل النقط دي تبقى مجتمعة مع بعض في نفس الوقت، الشخص ده هتبقى حياته عاملة إزاي\nهنشوف إن شاء الله مواقف من غيرة زوجات رسول الله ﷺ من بعضهن بعدين وهنشوف رد فعل رسول الله ﷺ كان بيبقى عامل إزاي\nإن شاء الله المرة الجاية هنشوف موقف قريش والقبائل العربية من دولة الإسلام، وهنعرف تحركاتهم بعد كده، هل هيستسلموا للمسلمين ولّا لسه هيحاربوهم تاني"}, {"n": 115, "l": "الجزء 89 | احداث السنه الخامسه من الهجره | تجميع اليهود للأحزاب", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_التاسعة_والثمانون\n#أحداث_السنة_الخامسة_من_الهجرة\n#تجميع_اليهود_للأحزاب\nاتكلمنا في الأجزاء الأخيرة إللي فاتت عن أهم الأحداث في السنة الرابعة من الهجرة، دخلنا دلوقتي في السنة الخامسة من الهجرة، \nوصل لرسول الله ﷺ أخبار عن إن القبائل في شمال الجزيرة العربية في منطقة دَوْمَة الجَنْدَل بدأوا يتجمعوا ويهجموا على القوافل إللي بتعدي ناحيتهم ويقتلوا منها المسلمين،\nفجهز رسول الله ﷺ جيش عشان يروح يقاتل القبائل دي، وكانت منطقة دَوْمَة الجَنْدل بعيدة عن المدينة بأكثر من أربعمائة وخمسين كيلو متر، \nرسول الله ﷺ خرج المرة دي مع الجيش بنفسه، بعد المشي أيام في الصحراء؛ وصل رسول الله ﷺ إلى دومة الجندل وقعد فيها وبدأ يرسل السرايا يعني مجموعات من المقاتلين حول المنطقة، \nالناس إللي كانت بتتجمع دي هربوا كلهم من رسول الله ﷺ ومحدش قاتله، خافوا منه ﷺ\nوبكده ثبّت أركان الدولة الإسلامية اكثر وأكثر، وانتشرت أخبار جيش المسلمين أكثر في الجزيرة العربية:\nالمجموعة إللي هربت من مكة وراحت المدينة وكانوا مضطهدين دلوقتي الناس بقت هي إللي تخاف وتهرب منهم، وكل ده في أقل من خمس سنين\nغزوة دومة الجندل كانت في ربيع أول من السنة الخامسة للهجرة،\nرجع رسول الله ﷺ مع جيشه إلى المدينة وانتشرت الأخبار في المدينة إن الناس هربوا من رسول الله ﷺ، \nالأحداث في الفترة الأخيرة كلها كانت في صالح المسلمين، وده أدى إلى إن المنافقين في المدينة يهدوا شوية بعد ما كانوا شمتانين في المسلمين بعد غزوة أحد، وكانوا عمالين يثيروا الفتن،\nفلقوا إن المسلمين استعادوا قوتهم فسكتوا عشان خافوا على نفسهم،\nقريش هي كمان وصل لها أخبار المسلمين وانتصاراتهم إللي ورا بعض فبدأت تحس بالقلق من قوة المسلمين إللي كل يوم بتزيد، \nوكمان تجارتها للشام لسه منقطعة بسبب المسلمين،\nفلازم يكون في حل، لكن هم مش عارفين يحلوا المشكلة دي إزاي\nحتى قبائل الأعراب البعيدة عن المدينة بدأت تحس بالقلق على نفسها، زي قبائل غَطَفَان إللي كان منها بعض القبائل إللي غدرت بالمسلمين في حادثة ماء الرجيع وبئر معونة،\nوطبعا مننساش اليهود سواء يهود بني قُرَيْظَة أو يهود منطقة خيبر ، هم كمان خافوا من قوة المسلمين إللي استطاعوا يخرجوا فرعين منهم من المدينة،\nومتبقّاش في المدينة غير يهود بني قريظة إللي كانوا لسه على العهد،\nواليهود في منطقة خيبر إللي في شمال المدينة كانوا قلقانين جدا، يعني كان تفكيرهم إن رسول الله ﷺ هيخلص على اليهود في المدينة وهيروح لهم بعد كده،\nقال يعني رسول الله ﷺ كان ظالمهم يا عيني ومكنوش هم إللي نقضوا العهد مع رسول الله ﷺ مرة بعد مرة \nوطبعا بني النُّضير بزعمائهم متوصُّوش\nبعد ما رسول الله ﷺ أخرجهم من المدينة وراحوا سكنوا في حصون خيبر نقلوا لهم كراهيتهم للإسلام والمسلمين، مع إن هم إللي ابتدوا ونقضوا العهد \nبس نقول إيه...يهود متخصصين في إنهم يقلبوا الحقائق ويخلوا الإنسان الكويس أسوأ ما خلق الله، بس مين يفهم\n☆زي مثلا كده لما حد ييجي يحكي لنا مشكلة، يقعد يتكلم عن الطرف التاني لدرجة إنه يخلينا نكرهه احنا كمان مع إننا ممكن منعرفش الطرف التاني ده أو نعرفه بس مشفناش منه حاجة وحشة،\nوإللي بيحكي ده ممكن يكون هو إللي غلطان أصلا  بس الأسلوب والكلام بيوصلنا لمرحلة الكره بدون ما نشعر،\nوممكن يخلينا نحكم له بالحق مع إنه ظالم، \nعشان كده رسول الله ﷺ حذرنا\nيقول :\n\" إِنَّمَا أَنَا بشَرٌ، وَإِنَّكُمْ تَخْتَصِمُونَ إِلَيَّ، وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَلْحَنَ بحُجَّتِهِ مِنْ بَعْضٍ؛ \nفأَقْضِي لَهُ بِنحْوِ مَا أَسْمَعُ، فَمَنْ قَضَيْتُ لَهُ بحَقِّ أَخِيهِ فَإِنَّمَا أَقْطَعُ لَهُ قِطْعَةً مِنَ النَّارِ\"\nيعني لو اتنين بينهم مشكلة وواحد بيعرف يتكلم بطريقة تقنع إللي قصاده بإنه على الحق والثاني يا عيني ظلمه مع إن هو إللي غلطان أو ملوش حق في أي حاجة، فأي شيء هياخده هيكون نار عليه يوم القيامة،\nأي حاجة بقى...أموال...أرض...بيت...حُكم\nده للناس للي بيتكلموا بس، فما بالكم بالأفعال،\nإللي بيزوّر عشان يأخذ حق مش حقه، وإللي بيقتل عشان يأخذ حق مش حقه، وإللي...وإللي...\nيوم القيامة هنشوف فضايح والله، ربنا يسترنا ويرحمنا برحمته\nدلوقتي بقى عندنا كفار قريش والمنافقين واليهود والقبائل العربية غير المسلمة كل دول عايزين يتخلصوا من رسول الله ﷺ ودولة الإسلام والمسلمين، \nأمنيتهم المجموعة دي تختفي من على وجه الأرض، مع إن رسول الله ﷺ معملهمش حاجة،\n واحنا شفنا الأحداث من ساعة البعثة، مين إللي بيتشتم ومش بيرد، ومين إللي كان بيتعذب ومش بيرد ومين إللي كان بيتقتل ومش بيدافع عن نفسه،\nوشفنا أخلاق رسول الله ﷺ والمسلمين قبل البعثة كانت إيه،\nوكل الأذى ده عشان رسول الله كان بيقول لهم آمنوا بالله وعايز يصلح المجتمع الفاسد ويبعد الناس عن الفواحش والمحرمات،\nبالضبط زي ما ربنا قال عن أصحاب الأخدود، فاكرين أول ماتكلمنا في السيرة، كانوا هم أول ناس اتكلمنا عنهم، \nلأن إللي حصل مع رسول الله ﷺ زي إللي حصل معاهم زي إللي هيحصل لأي حد يمشي في نفس طريق رسول الله ﷺ:\n\"وَمَا نَقَمُوا مِنْهُمْ إِلَّا أَن يُؤْمِنُوا بِاللَّهِ الْعَزِيزِ الْحَمِيدِ \"\nدي سنة كونية...طول ما في حق لازم يكون في باطل يدفعه ويحاربه،\nطول ما في أصحاب الأخدود هيبقى في ذو نُوّاس وجماعته،\nطول ما في رسول الله ﷺ والصحابة هيبقى في قريش وإللي بيساعدهم،\nلو ملقتوش باطل بيحارب حق، يبقى ده مش حق ده باطل متزين بالحق مش أكثر،\nأما الحق الصحيح هتلاقوا الدنيا كله ضده وبتحاربه عشان تقضي عليه\nوهو ده إللي هيحصل دلوقتي مع رسول الله ﷺ، \nقبائل العرب كلهم كانوا متفرقين عايشين على الهجوم على بعض سنين طويلة من قبل الإسلام، \nعمرهم ما اجتمعوا على حاجة، كل قبيلة لها زعيمها ولها قوانينها الخاصة، حتى رسول الله ﷺ لما كان بيحارب كان بيحارب كل قبيلة لوحدها،\nالقبائل المتفرقة دي اليهود قدروا إنهم يجمعوهم كلهم تحت راية واحدة بهدف واحد وهو القضاء على الإسلام والمسلمين،\nمش بس حرب بينهم ويحددوا المنتصر، لأ...ده عايزين يبيدوهم إبادة، ميتبقاش واحد منهم على ظهر الأرض\nاليهود بقيادة حُيَي بن أخطب زعيم بني النَّضير وأبو رافع سَلاّم بن أبي الحُقِيق إللي راحوا مع قومهم يسكنوا في خيبر مقهورين من إللي اتعمل فيهم هم وقومهم، ومش قادرين يستحملوا القهرة إللي هم فيها،\nإزاي المسلمين يبقوا قاعدين متهنيين كده في أرضهم\nفالحقد ده خلاهم يتحركوا لجمع قبائل العرب كلهم تحت راية واحدة، \nالموضوع مش سهل، يعني مش هيتصلوا بيهم بالتليفون ويخلصوا الموضوع\nده هيسافروا من مكان لمكان على الجمال، ومحتاجين أموال كثيرة جدا، ومفاوضات وإقناع الناس يعني فعلا وجع قلب\nأبو رافع سلاّم بن أبي الحقيق ده كان رجل فااااحش الثراء، عنده أموال كثيرة جدا، خرج مع حُيَي بن أخطب في جولة مفاوضات،\nفكان هو إللي بيصرف على المفاوضات دي،\nراح لقريش وقال لهم:\nعندكم فرصة دلوقتي للقضاء على محمد وأصحابه، هنجمع لكم قبائل العرب المتفرقة تحت قيادتكم وتحاربوا محمد وتخلصونا منه\nطبعا فرصة ذهبية لقريش، ده لسه من كم شهر اضطرينا نرجع عشان خايفين وشكلنا بقى وحش قصاد العرب،\nفطبعا وافقوا وبدأوا يجمعوا من القبائل حولهم لحد ما جمعوا أربعة آلاف مقاتل،\nقادة اليهود تركوهم يجمعوا المقاتلين وبسرعة راحوا لقبائل غطفان في شرق الجزيرة العربية،\nقبائل غطفان قبائل كبيرة جدا، في منهم إللي عملوا مع رسول الله ﷺ صُلح زي زعيم بني فِزَارة عُيَيْنَة بن حِصن، وفي قبائل تانية لم تعاهد رسول الله ﷺ على صلح ولكنهم كانوا خايفين من قوة المسلمين،\nالمهم اليهود اجتمعوا مع رؤساء قبائل غطفان من هنا وهناك،\nحاولوا يقنعوهم لكنهم متشجعوش أوي بسبب خوفهم من المسلمين،\nاليهود ميأسوش، \nتخيلوا إن اليهود البخلاء إللي بيحبوا المال جدا قالوا لقبائل غطفان لو انتم شاركتم في الحرب دي هنعطيكم ثمار خيبر لمدة سنة كاملة، يعني كل ما تطلع زرعة في أي مكان من حصون خيبر هي لكم،\nخيبر دي أرض خصبة جدا وثمارها كثيرة جدا، ثمنها آلاف الدنانير الذهب، وهي أحلى ثمار في الجزيرة،\nوطبعا قادة قبائل غطفان وافقوا بقيادة عُيَيْنة بن حصن ونقض العهد مع رسول الله ﷺ ، حد يلاقي فلوس زي الرز ويقول لأ\n☆اليهود يا جماعة عشان يصدوا عن سبيل الله ويقضوا على دولة الإسلام بذلوا وقتهم وجهدهم وأموالهم إللي بيحبوها وهم على باطل،\nاحنا مش عارفين نبذل وقتنا وجهدنا وأموالنا لنصرة الإسلام\nنقدر والله نبذل وقتنا في إننا نتعلم دين ربنا صح، نقدر والله نبذل مجهود في توصيل الدين للناس إللي متعرفش حاجة ونصبر على الأذى،\nنقدر والله نبذل الأموال ونساعد المحتاجين، كل واحد على أد استطاعته، \nلو كل واحد بص حواليه هيلاقي حد محتاج يثق فيه، بس احنا إللي مش عايزين نبذل عشان خايفين من المستقبل ونقول محدش يعرف الأيام الجاية فيها إيه،\nوناسيين إن الأيام الجاية ممكن تيجي واحنا مش موجودين فيها أساسا،\nخليكم فاكرين كويس أوي إن كل المجهود والوقت والمال إللي بنبذله في سبيل الله في الدنيا، هنلاقيه في القبر على هيئة رجل صالح يقعد معانا في القبر يونسنا إلى قيام الساعة\nقبائل غطفان جمعت ستة آلاف مقاتل \nوعندنا أربعة آلاف جمعتهم قريش يبقى دلوقتي الجيش وصل لعشرة آلاف مقاتل هيروحوا المدينة وهدفهم الهجوم على المسلمين وإبادتهم إبادة\nالجيش ده كان أكبر جيش يتكون في تاريخ العرب كلهم في زمانهم،\nعشان بس تتصوروا معايا الموقف، سكان المدينة كووولهم حتى بالأطفال إللي لسه مولودين عددهم أقل بكثير من العشرة آلاف دول، يعني بالحسابات المادية المشركين هيكتسحوا المسلمين\nفي الوقت إللي اليهود شغالين بيجمعوا المشركين عشان يحاربوا المسلمين، كان الخبر وصل لرسول الله ﷺ\nرسول الله ﷺ زارع عيون في كل مكان، شبكة مخابرات تنقل له الأخبار أول بأول،\nرسول الله ﷺ مش معتمد على إنه رسول والوحي هيجيله فيقعد بقى مستني، لأ...ده كان بياخد بالأسباب لأنه زي ما قلنا قبل كده إنه قدوة لكل إللي هييجوا بعده فلازم يورينا خطوات إزاي نجمع المعلومات\nفعرف رسول الله ﷺ إن اليهود بيتحركوا لجمع المشركين لحرب المسلمين، \nوكل شوية الأخبار بتتحدِّث، يعني قريش جمعت كذا وغطفان جمعت كذا لحد ما وصل له الخبر إن المشركين جمعوا عشرة آلاف مقاتل،\nرسول الله ﷺ موقفش يتفرج ويستناهم لحد ما ييجوا، بدأ يخطط ويفكر مع الصحابة إزاي هيحلوا المشكلة ويدافعوا عن المدينة،\nلكن قبل ما نعرف إللي حصل خلونا نشوف الحدث الجميل إللي حصل وإللي فرّح رسول الله ﷺ جدا لأنه كان حدث أول مرة يحصل،\nفي قبيلة اسمها مُزَيْنَة بتسكن بالقرب من المدينة، يعني زي ما بنقول على نفس الخط كده، الرايح والجاي عليهم كان بيتكلم عن رسول الله ﷺ وعن الصحابة وعن الإسلام بكل خير والناس في قبيلة مُزَينة كانوا ناس مُنصفين،\nيعني كانوا بيقولوا عالصح صح والخطأ خطأ حتى لو كانوا أعدائهم، مش زي أبو جهل وغيره لما جاءههم رسول الله ﷺ بالحق كذبوه عشان مش عاجبهم واتهموه بالكذب ظلما وعدوانا\nفي يوم من الأيام سيدهم النُّعمَان بن مُقَرّن قعد مع مشايخ قبيلته وإخوته وكانوا عشرة إخوة وقال لهم:\nيا قوم! والله ما علمنا عن محمدٍ إلا خيرا، ولا سمعنا من دعوته إلا مرحمة وإحسانا وعدلا، فاحنا مستنيين إيه والناس بتسرع له ويسلموا\nأما أنا، بكرة الصبح على طول هروح لمحمد وأُسلم ، إللي عايز ييجي معايا يجهز نفسه\nتاني يوم الصبح صحي النُّعمان بن مُقَرّن واستعد وخرج عشان يروح لرسول الله ﷺ لقى إخوته العشرة ومعاهم أربعمائة فارس من فرسان مُزَيْنة اتجهزوا عشان يروحوا معاه يسلموا عند رسول الله ﷺ \nهو قال كلمتين بس وكان صادق فيهم ونفذهم، عشان كده ربنا جعله سبب في إسلام المجموعة دي.\n☆شوفتم القدوة ممكن تعمل إيه\nهو اتكلم ونفذ فورا، خلونا نربط موقف النعمان بواقعنا كده،\nالطبيب...المهندس...المعلم...رئيس مستشفى...أب...أم.....داعية...أي حد في موضع قيادة قام عمل الصح فهو قدوة لغيره،\nكل ما كان الإنسان شأنه عالي وسط الناس وكان قدوة في الخير كل ما كان أجره أعلى بسبب الناس إللي هيتبعوه،\nتخيلوا لو الطبيب بيدخن، هيقدر يقول للمريض بكل ثقة لازم تسيب التدخين عشان بيضر بصحتك؟\nطبعا لأ، لأن أول كلمة المريض هيقولها للطبيب مانت بتدخن اهه يا دكتور\n《طبعا التدخين حرام شرعا بس أنا هنا بتكلم من ناحية الطب》\nمحدش يستهين بكلمة يقولها ولا فعل يفعله، سواء في الخير أو في الشر، فاكرين إبليس، خرج من رحمة ربنا بسبب ذنب واحد،\nوصاحب الرغيف ربنا تاب عليه بعمل واحد فقط،\nوامرأة بغي ربنا غفر لها ذنوبها لأنها سقت كلب، \nطبعا هنعرف قصتهم بس بعدين إن شاء الله\nلكن لحد ما نعرف قصتهم اجتهدوا إنكم تبعدوا عن المعاصي حتى لو كانت في نظركم حقيرة،\nواعملوا الطاعات حتى ولو كانت في نظركم بسيطة، محدش يعرف أنهو عمل هيكون سبب في دخول الجنة\nالنعمان بن مُقرن مع إخوته والفرسان اتجهزوا وهيروحوا يقابلوا رسول الله ﷺ، لكن النعمان محبش يروح لرسول الله ﷺ بالجمع الكبير ده وإيده فاضية، وخصوصا إنه عارف إن المسلمين كانوا فقراء ومحتاجين،\nالمهم قعد يدور من هنا لهنا لحد ما طلع له بعض الأغنام ياخدها معاه لرسول الله ﷺ وكانت السنة دي سنة جَدب فمكنش عندهم زرع ولا أغنام كثيرة،\nوصل النعمان وإخوته والفرسان، وضجت المدينة بالناس الجايين دول، يعتبر جيش صغير، متخيلين إن المسلمين في غزوة بدر كانوا في حدود الثلاثمائة وخمسة عشر أو سبعة عشر مقاتل\nدول لوحدهم أكثر من أربعمائة وإيه داخلين على الفرس بتاعهم ، يعني منظر رهيب،\n ودخلوا على رسول الله ﷺ وأعلنوا إسلامهم، ففرح بهم رسول الله ﷺ فرح شديد جدا،\nواهتزت المدينة كلها بالخبر ده، أول مرة العدد ده يسلم مرة واحدة، وأول مرة بيت من بيوت العرب يسلم منه العدد الكبير ده، \nإحدى عشر أخ مرة واحدة\nوتقبل الله منهم وأنزل فيهم قرآن قال تعالى:\n\"وَمِنْ الْأَعْرَابِ مَنْ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَاتٍ عِنْدَ اللَّهِ وَصَلَوَاتِ الرَّسُولِ أَلَا إِنَّهَا قُرْبَةٌ لَهُمْ سَيُدْخِلُهُمْ اللَّهُ فِي رَحْمَتِهِ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ\"\nلما كانوا خلاص هيمشوا قال بعضهم لرسول الله ﷺ:\nمعندناش طعام نتزود به!\nيعني وهم ماشيين في السفر معندهمش طعام ياكلوه، أكلهم خِلص،\nفقال رسول الله ﷺ لعمر بن الخطاب رضي الله عنه: زوّدهم يا عمر!\nيعني أعطيهم أكل معاهم، فعمر قال له: معنديش غير بواقي تمر، ومظنش إنها هتكفيهم!\nفراحوا كلهم مع عمر ...الأربعمائة فارس، فصعد عمر في عِلّيّة له ، زي الصندرة كده فيها تمر، فقال للفرسان: خذوا!\nفأخذوا كل إللي كانوا محتاجينه، وكان النعمان آخر واحد أخذ من التمر، بيقول : \nفالتفت- بص وراه يعني- لقيت التمر زي ما هو ومفيش ولا تمرة اتشالت من مكانها مع إن في أربعمائة رجل أخذوا منه.\nوكانت دي من معجزاته ﷺ\nالأخبار عمالة بتصل للمدينة عن جيش المشركين إللي كل شوية عمال يزيد، وخلاص هيبدأوا يتجهوا للمدينة، \nطبعا خبر تجمع المشركين بالأعداد الرهيبة دي، كان له تأثير كبير على أهل المدينة\nياترى كان رد فعل أهل المدينة كان إيه، ويا ترى إيه الخطة إللي رسول الله ﷺ هيستعملها في الدفاع عن المدينة،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 116, "l": "الجزء 90 | أحداث السنه الخامسه من الهجره | حفر الخندق", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_التسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#حفر_الخندق\nاتكلمنا المرة إللي فاتت عن تجميع اليهود للمشركين من كل الجزيرة العربية عشان يكوّنوا جيش ييجي يقضي على المسلمين في المدينة،\nجمعوا فعلا أكبر جيش تشهده الجزيرة العربية في تاريخها وكان عددهم عشرة آلاف مقاتل، وصل الخبر لرسول الله ﷺ وأخبر أهل المدينة عن الجيش ده،\nالخبر كان ثقيل جدا على أهل المدينة، لكن المؤمنين الصادقين كانوا عارفين إن هو ده الطبيعي،\nعارفين إن الدنيا كلها هتجتمع على حربهم وعارفين إن النصر من عند ربنا وهو هينصرهم لو هم نصروه باتباع منهجه سبحانه وتعالى\nفبدأوا يستعدوا ويجهزوا نفسهم مع رسول الله ﷺ عشان يشوفوا خطة لحرب الجيش القادم ده،\nأما بقى المنافقين فكانوا مرعوبين، إزاي هيحاربوا عشرة آلاف\nأصل هم ميعرفوش غير الحسابات المادية، معندهمش قناعة بقدرة ربنا...لأنهم مش مسلمين، دول ناس أظهروا الإسلام فقط...الإيمان مدخلش قلوبهم، فربنا ملوش وجود في حياتهم،\nمش قادرين يفهموا إن الكون ده كله ملكه...مش قادرين يتصوروا إن ربنا إذا أراد شيئا فإنما يقول له كن فيكون،\nفقرروا عدم القتال وهيتحججوا بأي حجة عشان يهربوا من القتال، \nوياريتهم سكتوا على كده دول حاولوا يمنعوا المسلمين من القتال ويثبطوهم ويقولوا لهم مفيش فايدة من القتال وأحسن حاجة إننا نستسلم لهم عشان نحافظ على حياتنا، وعادي لو اتنازلنا شوية يعني أهم حاجة نحافظ على حياتنا،\n\"قَدْ يَعْلَمُ اللَّهُ الْمُعَوِّقِينَ مِنكُمْ وَالْقَائِلِينَ لِإِخْوَانِهِمْ هَلُمَّ إِلَيْنَا ۖ وَلَا يَأْتُونَ الْبَأْسَ إِلَّا قَلِيلًا\"\nوالناس دي للأسف مش فاهمة إن المسلم الصادق أغلى أمنية عنده إنه يموت في سبيل الله\nوهنا بقى بدأ التَّمايُز، يعني الإبتلاءات والأزمات بتكشف عن معادن الناس وعن إللي في قلوبهم،\n\"مَّا كَانَ اللَّهُ لِيَذَرَ الْمُؤْمِنِينَ عَلَىٰ مَا أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ الْخَبِيثَ مِنَ الطَّيِّبِ\"\nالمؤمنين هيعرفوا المنافقين على حقيقتهم بسبب هروبهم من تحمل المسؤولية\n☆صادق الإيمان عارف إنه كل ما تقدم في طريق الله هيقابل الابتلاءات، فلما يصبر ويستمر بيقين ربنا بيرفع عنه البلاء وينصره،\nأما ضعيف الإيمان أو المنافق لما يواجهه بلاء تلاقيه رجع وبدأ يتسخط ويقول يعني هي دي مكافئتي...بقى أنا بعمل إللي يرضي ربنا وهو يبتليني...مانا لو مكنتش مشيت في طريق الطاعة مكنش حصل لي حاجة\nعشان كده لازم الأزمات ولازم الابتلاءات....ليميز الله الخبيث من الطيب...ليميز الله الصادق في إيمانه من الكاذب، ربنا يجعلنا وإياكم من الصادقين الطيبين\nاجتمع رسول الله ﷺ مع الصحابة عشان يستشيرهم ويشوفوا حل، وده كان عادته ﷺ، \nفاكرين قبل غزوة بدر وقبل غزوة أحد كان بيستشير أصحابه يعملوا إيه،\nوده فيه تأكيد إن المسلم هو صاحب القضية، يعني مش رسول الله ﷺ هو بس يقول القرارات وخلاص والناس تنفذ،\nكان بيُشركهم معاه وبيحسسهم إن الإسلام ده بتاع كل واحد فيهم، وإن كل واحد رأيه مهم..كبير أو صغير..عربي أو غير عربي\nكان حاضر مع الصحابة في الوقت ده سلمان الفارسي رضي الله عنه لو تفتكروا قصته اتكلمنا عنه في الجزء الثاني والخمسين،\nوده كان أول مشهد يشهده مع رسول الله ﷺ، محضرش معاه غزوة بدر ولا أحد ولا أي غزوة قبل كده،\nوده لأنه كان لسه عبد عند اليهودي، فرسول الله ﷺ أراد إنه يحرره فقال له: كاتِب يا سلمان!\nيعني يتفق مع اليهودي على مبلغ معين يعطيه له سلمان مقابل إنه يحرره،\nفاتفقوا إن سلمان يزرع لليهودي ثلاثمائة نخلة ويعطيه أربعين أوقية من الذهب،\nواحنا قلنا قبل كده إن الأوقية في العهد النبوي كانت حوالي ثلاثين جرام إلا ربع من الذهب،\nرسول الله ﷺ قال لأصحابه أعِينوا أخاكم\nفبدأ كل واحد يعطيه من عنده إللي يقدر عليه لحد ما جمع الثلاثمائة نخلة، بس مش النخلة الكبيرة أوي\nهو جمع نخل صغير عشان يعرف يزرعه، فلما حفروا مكان الحفر رسول الله ﷺ قال له إن هو إللي هيضع النخل بيده الشريفة ﷺ،\nووضع رسول الله ﷺ الثلاثمائة نخلة في مكانهم في الحفر، ولم تمت منهم نخلة واحدة،\nوبكده أدى سلمان أول جزء من الاتفاق، باقي الأربعين أوقية،\nجاء لرسول الله ﷺ في الغنائم من الغزوات بيضة من الذهب  في نفس حجم بيضة الدجاجة كده،\nفسأل عن سلمان عمل إيه في المال إللي كان فاضل عليه، فأرسل له رسول الله ﷺ فجاءه سلمان وأعطاه البيضة من الذهب وقال له خذها وأدي بها ما عليك،\nفسلمان قال لرسول الله ﷺ: دي متجيش حاجة جنب إللي عليّ\nفقال له رسول الله ﷺ: خذها فإن الله سيؤدي بها عنك\nأخذ سلمان البيضة وراح وزنها وطلع منها الأربعين أوقية كاملة\nوبكده أخذ سلمان حريته بعد سنين في الرق والعبودية،\nومن ساعة ما أخذ حريته وهو بقى مع رسول الله ﷺ وحضر معاه كل الغزوات وأولهم غزوة الأحزاب أو غزوة الخندق إللي احنا بنحكي عنها دلوقتي\nبدأ رسول الله ﷺ مع الصحابة يشوفوا الخطة إللي هيواجهوا بها الجيش القادم للمدينة،\nفي رواية بتقول إن سلمان الفارسي اقترح على رسول الله ﷺ إنهم يحفروا الخندق، وقال له إنه كان عندهم في الفُرس لما الجيوش بيحاصروهم كانوا بيحفروا خندق حولهم عشان يقدروا يمنعوا الأعداء من الهجوم،\nوالرواية إللي فيها اقتراح سلمان بحفر الخندق دي العلماء اختلفوا فيها،\nفي علماء قالوا إن الرواية دي ضعيفة، وإن إللي قال بحفر الخندق هو رسول الله ﷺ نفسه، وعلماء تانيين بيقولوا إنها صحيحة، فأنا قلت لكم الرأيين من باب الأمانة \n☆وبما إننا بنتكلم عن الصحيح والضعيف، ففي حديث مشهور بين الناس ولكنه حديث ضعيف جدا لايصح، وهو حديث : \"سلمان منا آل البيت\"\nنرجع بقى للخندق وإزاي المسلمين حفروه، الخندق ده عبارة عن حفرة كبيرة وطويلة ولازم يكون عريض، عشان الفَرَس لو حاول ينط ميعرفش يعدي الناحية التانية، زي نط الحواجز كده عارفينه\nالمدينة مكان محمي حماية طبيعية من كل الجهات بالصخور والغابات، ما عدا جهتين، وده من تقدير ربنا إن المكان إللي كان هيهاجر له رسول الله ﷺ يساعده على حمايته وحماية المؤمنين معاه،\nفكانت المدينة محمية ما عدا جهتين،\nجهة يسكنها يهود بني قريظة، ويهود بني قريظة دول كانوا على عهد مع رسول الله ﷺ إنه يدافعوا عن المدينة مع المسلمين ضد أي هجوم خارجي عليهم،\nولا يعاونوا أي أحد بينه وبين المسلمين عداء، فأرسل لهم رسول الله ﷺ عشان يؤكد عليهم العهد فقالوا له إنهم على العهد،\nوالجهة التانية هي الجهة الأمامية المفتوحة ودي إللي المشركين هييجوا منها وده المكان إللي قرر رسول الله ﷺ إن الخندق يتحفر فيه\n☆ممكن حد يسأل هو كده المسلمين مش جبناء، وإزاي يحفروا خندق وميقاتلوش المشركين\nشوفوا يا جماعة، الإسلام دين واقعي، أيوة ربنا معاهم وهو إللي بينصرهم، بس لازم الأخذ بأسباب النصر المادية،\nمينفعش أقول أنا بطيع ربنا وبعمل كل إللي بيأمرني بيه فخلاص بقى أقعد في بيتي وهو هيبعتلي رزقي لحد عندي،\nلازم أخذ بالأسباب وأنزل وأشتغل عشان يجيلي الرزق،\nكذلك هنا لازم الأخذ بأسباب النصر المادية، عدد المسلمين إللي هيقدروا يدافعوا عن المدينة ثلاثة آلاف، وجيش المشركين عشرة آلاف قابلة للزيادة،\nيعني ممكن يهود خيبر ينضموا للجيش، ممكن قبائل تانية تيجي وتشارك،\nفطبعا الفرق واضح، مش شطارة إني أواجه حد وأنا مش مستعد له باللي أقدر عليه،\nلما أعمل إللي في إيدي كله وأبذل استطاعتي كلها إللي ربنا يعلمها ويعلم إن ده أخري، هنا ربنا يساعدني وينصرني،\nلكن أقعد واستنى النصر من غير ما اتعب وابذل مجهود وأقول مانا بدعي ربنا\nأكيد طبعا مش هيبقى في أي نصر\nأنا كمسلم بستغل كل حاجة ممكن تخليني أنتصر مادامت مشروعة ومفيش نهي عنها،\nوفكرة الخندق كانت فكرة ممتازة جدا، لأن الجيش لما ييجي هيفضل قاعد الناحية التانية مش هيعرف يعدي،\nوطبعا جيش بالحجم ده مش هيقدر يقعد بعيد عن بلاده فترة طويلة، لأنهم هيحتاجوا أكل وهيحتاجوا ماء وتجارتهم هتتعطل،\nيعني عامل الزمن هنا في صالح المسلمين، فالمطلوب إن المسلمين يصبروا شوية وساعتها المشركين هيضطروا يرجعوا حتى من غير قتال\nاتفقوا خلاص على حفر الخندق، وإذا كان القرار سهل وسريع، فالتنفيذ مستحيل\nعايزاكم تتخيلوا معايا كده، المطلوب إنهم يحفروا خندق طوله اثنا عشر كيلو متر، وعمقه خمسة أمتار وعرضه في أقل التقديرات خمسة أمتار وبعض التقديرات بتقول إن العرض كان عشرة أمتار، في زمن مفهوش أي آلات حَفر ومعدات تشيل التراب، يعني الكل هيشتغل بإيده\nوكل ما كان العمق أكثر قدرة العامل على الحفر بتقل، لأنه لازم يحفر في أرض أصعب وكمان لازم يطلع التراب وينقله في مكان بعيد، وبعدين يرجع ينزل ويحفر وهكذا، \nأو تكون في فرق مخصصة عشان تنقل الكمية الكبيرة جدا من التراب دي، \nوعدد المسلمين أصلا ثلاثة آلاف ومش كلهم هيحفروا في الخندق، لأن في منهم هيبقى مهمته الحراسة...وفي منهم إللي سنه كبير فمش هيقدر يحفر وفي منهم إللي كان  مريض،\nومع ذلك لو كلهم شاركوا في الحفر فمستحيل يقدروا يخلصوا في أسبوعين قبل ما يأتي جيش المشركين، فمحتاجين كل صحابي يشتغل على الأقل ستة عشرة ساعة يوميا، ده على اعتبار إن الأرض رملية وسهلة ومفيش صخور هتعترضهم\nلكن الواقع إن الأرض صخرية محتاجة معدات خاصة وأجهزة حفر متطورة، والمسلمين أصلا معندهمش خبرة في المجال ده، أول مرة يحفروا خندق، \nوتخيلوا بقى إن المسلمين المفروض يتوزعوا على مجموعات على طول الإثنا عشر كيلو، مين إللي هيُدير المجموعات دي رايح جاي،\nوفوق كل ده المسلمين كانوا هيحفروا الخندق في ظروف صعبة جدا من الجوع والبرد وخوف من قدوم الأعداء،\nحفر خندق زي ده في زماننا عشان يخلص في أسبوعين محتاج أكثر من مئتي لودر، الآلة إللي بتشيل التراب،\nوشواكيش إلكترونية والعشرات من سيارات النقل عشان تنقل التراب، ومحتاجين مجموعة من الاستشاريين المتخصصين في الحفر،\nدكتور راغب السرجاني بيقول إنه قعد مع مهندس عشان يحسبوا حجم مشروع حفر الخندق ده بالورقة والقلم، المهندس رمى القلم من يده وقال له:\nالموضوع ده خارج إمكانيات البشر\nالموضوع فعلا صعب، إزاي الصحابة قدروا يحفروا الخندق ده\nالبشر في العادة ميقدروش يعملوا العمل ده، لكن الله سبحانه وتعالى إذا أراد إنهم يعملوا هيخليهم يعملوا ويتموا المشروع، سواء بأيديهم وإنه يعطيهم القوة، أو يؤيدهم بالملائكة تساعدهم، ويرزقهم البركة في الوقت والجهد\nبدأ المسلمون في حفر الخندق ومعهم رسول الله ﷺ، رسول الله ﷺ مقلهمش يلا يا رجالة ورُّونا الهمة واحفروا ولما تخلّصوا اندهولي، وراح قعد في بيته مستني المسلمين يخلصوا\nرسول الله ﷺ حاكم المدينة، النبي المرسل المُطاع والقائد الأعلى لجيش المسلمين نزل بنفسه يحفر مع المسلمين،\nمش واقف يهندس عليهم ويقول لده اعمل وده متعملش،\nده ماسك المِعْول بيضرب به الأرض وبيحفر،\nوالتراب كان مغطيه لدرجة إن الصحابة مكنوش شايفين بطنه من كثرة التراب إللي مغطيها\nووزع رسول الله ﷺ الأعمال بين المسلمين، مفيش حد أحسن من حد ومفيش حاجة اسمها واحد قاعد كده كسلان مش بيشتغل،\nكان بيعطي كل عشرة من الصحابة أربعين ذراع يحفروها ولما يخلصوها يأخذوا غيرها وهكذا،\nحصلت أحداث ومعجزات أثناء حفر الخندق، هنعرفها إن شاء الله الجزء الجاي\n♡"}, {"n": 117, "l": "الجزء 91 | احداث السنه الخامسه من الهجره | حفر الخندق", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_الواحدة_والتسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#المعجزات_في_حفر_الخندق\nاتكلمنا المرة إللي فاتت عن خطة رسول الله ﷺ مع المسلمين في الدفاع عن المدينة، والخطة كانت إنهم يحفروا خندق في المكان إللي هييجي منه جيش المشركين،\nوزّع رسول الله ﷺ الصحابة على طول الخندق وأعطى كل عشرة منهم أربعين ذراع يحفروه يعني حوالي أربعة وعشرين متر، \nوبدأ المسلمون بحفر الخندق ومعهم رسول الله ﷺ، كان بيحفر ويشيل معاهم التراب ﷺ، وكانوا بيحفروا طول اليوم،\nوطبعا كده أشغالهم وقفت لأن وقتهم كله كان في حفر الخندق،\nومحدش فيهم قال لرسول الله ﷺ طيب احنا هناكل إزاي دلوقتي يا رسول الله،\nولا طلبوا منه إنه يُؤَمّن لهم أكل في مقابل إنه يتركوا شغلهم ويحفروا الخندق، الصحابة كان عملهم كله لله مكنوش بيشترطوا أي شيء أبدا في مقابل تضحيتهم ولا كانوا بيستنوا الجزاء في الدنيا\nوانتم عارفين إن الحفر ده عمل شاق،\nفكانوا بيخففوا عنهم مشقة العمل بالإنشاد، كان في واحد من الصحابة شاعر اسمه عبد الله بن رواحة من الأنصار من قبيلة الخزرج،\nوكان من إللي حضروا بيعة العقبة الثانية ومن أوائل من أسلم من الانصار، فقال أبيات من الشعر وكررها الصحابة حتى رسول الله ﷺ كان يقولها ويمد بها صوته:\n وَاللَّهِ لَوْلَا أَنْتَ ما اهْتَدَيْنَا... وَلَا تَصَدَّقْنَا وَلَا صَلَّيْنَا\n فَأَنْزِلَنْ سَكِينَةً عَلَيْنَا... إنَّ الأُلَى قدْ بَغَوا عَلَيْنَا  \n إذَا أَرَادُوا فِتْنَةً أَبيْنَا..\nفكان رسول الله ﷺ يمد كلمة أبينا ويقول أبيناااااا، كأنه بيعلن عن تصميمه وثباته على الدين ﷺ \nفي يوم من الأيام خرج رسول الله ﷺ للخندق وكان في يوم بارد فلقى الأنصار والمهاجرين بيحفروا ومكنش عندهم عبيد يساعدوهم أو يشتغلوا مكانهم،\nفلما شاف إللي فيهم من الجوع والتعب قال وكأنه بيعزيهم عن فوات الدنيا و بيشجعهم ويذكرهم إنهم موجودين في الدنيا للجهاد، مش عشان يعيشوا منعمين، وإن النعيم في الآخرة:\nاللهم لا عيشَ إلا عيشُ الآخرة فاغفر للمهاجرين والأنصار،\nفرد عليه الصحابة وقالوا له :\nنحن الذين بايعوا محمدا***على الجهاد ما بَقِينا أبدَا\nوكأن الصحابة كانوا بيؤكدوا على كلام رسول الله ﷺ وإن العيش فعلا هو عيش الآخرة\n☆وهنا في فائدة وهي إن الإنسان لما يشوف حاجة تعجبه يقول :\nاللهم إن العيش عيش الآخرة، وهو من السنة،\nعشان يفكر نفسه بغربته في الدنيا، وإنه مهما أخذ إللي بيتمناه في الحياة فهو زائل... هيسيبه ويمشي ويروح في الآخرة إللي فيها الحياة الحقيقية والنعيم الحقيقي الذي لا يزول، \nولو بصينا للواقع هنلاقي إن احنا مضعناش غير لما نسينا الآخرة وبقى همنا كله في المتعة الدنيوية...متعة الأكل والشرب...متعة لبس الماركات العالمية...متعة السكن في أبهى الشقق والتفنن والمبالغة في زخرفتها،\nوكل ده محتاج للمال والسعي،\nوالإنسان بطبيعته البشرية لما يشوف حاجة تعجبه قلبه يتمناه ويبقى عايز الحاجة دي، \nفممكن يترك عبادة الله ويُعرض عن الله عشان يحقق إللي نفسه فيه،\nهمه في الحياة إنه يأكل ويشرب ويتزوج ويحقق أحلامه وخلاص خلصت الدنيا على كده وكأنه لن يموت،\nوكم سمعنا عن ناس 《أفنُوا أعمارهم》 عشان يشتري البيت إللي بيحلم بيه وفي الآخر يموت من قبل حتى ما يسكنه،\nوناس تانية 《تضيع عمرها كله》 في جمع الأموال وميهمهاش هي جمعت المال ده من حلال ولا من حرام، وتبقى حتى بخيلة على نفسها وفي الآخر تموت من غير ما تستمتع بالأموال دي ويأخذها الورثة\nفلما الإنسان يُذَكّر نفسه إن العيشة الحقيقية في الآخرة بس، ده هيقصر أمله ويخليه يزهد في الحاجة إللي عجبته دي ويبقى عنده قناعة ويوجه الإنسان نفسه وهمّه للآخرة،\nومَن كانت الآخرة همّه جعل الله غِناه في قلبه\nوالصحابة شغالين في حفر الخندق، جاء واحد منهم لرسول الله ﷺ وقال له: يا رسول الله أنا جعان ومش لاقي أكل، شوف، أنا حتى رابط على بطني حجر من شدة الجوع\n وكشف الرجل عن بطنه عشان يوري رسول الله ﷺ الحجر إللي هو رابطه بحبل على بطنه، \n☆وكان من عادة العرب إنهم لما يجوعوا يربطوا حجر على بطنهم عشان ميحسوش بالجوع والحجر كمان بيوزن الجسم ويخلي الإنسان واقف مستقيم، لأن البطن لما تكون فاضية الجسم بينحني للأمام على البطن، ده غير إن برد الحجر بيهدئ من الإحساس بالجوع.\nرسول الله ﷺ شاف منظره والموقف مؤثر، هيقول له إيه عشان يصبره في موقف زي ده،\nرسول الله ﷺ مقلهوش أي كلام يصبره، ولا قال له ياريتني كنت أنا يا أخي\nرسول الله ﷺ حاكم المسلمين...النبي المُرسل...القائد الأعلى لجيش المسلمين قال له:\nانظر! وكشف رسول الله ﷺ عن بطنه فرآه الرجل رابط حجرين على بطنه ﷺ \nرسول الله ﷺ كان أشد جوعا منه، الرجل لما شاف قدوته في الحالة دي صبر ومتكلمش، القائد طول ماهو قريب من أحاسيس ومشاعر ومعاناة رعيته هيبقوا أقوياء ويستحملوا المشقة ويجتهدوا أكثر \nوعشان أي عمل جماعي ينجح لازم القائد نفسه يشارك الناس إللي تحته في مشاكلهم وهمومهم،\nوفعلا ده إللي حصل، المسلمين كانوا بيجتهدوا في الحفر لما كانوا بيشوفوا رسول الله ﷺ بيشيل التراب على كتفه والتراب غطى وجهه ولحيته وصدره، \nلدرجة إنهم قالوا له احنا نشتغل بدالك يا رسول الله، فكان يقول لهم لستم أَوْلَى بالأجر مني\nده الكلام ده ورسول الله ﷺ عمره فوق الخمسة وخمسين سنة، رسول الله ﷺ وهو المغفور له ما تقدم من ذنبه وما تأخر بيقول لهم لستم أَوْلى بالأجر مني،\nفليه احنا بنفرط في أجور كثيرة حتى وهي أعمال بسيطة مش محتاجة مجهود زي كده\nجابر بن عبد الله بن حرام شاف رسول الله ﷺ بالمنظر ده، وأد إيه الجوع ظاهر على وجهه ومأثر فيه، كان بقى له هو والصحابة ثلاثة أيام مأكلوش حاجة خالص مع المجهود إللي بيعملوه ده تخيلوا\nوكان أقصى حاجة ممكن ياكلوها إن الواحد منهم يضع تمرة في فَمه ويقعد يمصها ويشرب عليها المية \nفاستأذن جابر رسول الله ﷺ إنه يروح لبيته، فأذن له رسول الله ﷺ، طبعا مكنش في حد بيسيب مكانه كده لما يستأذن، \nلأن كل واحد فيهم كان عارف المسؤولية إللي عليه، وعارف أهمية العمل إللي هم فيه\nوربنا قال عنهم:\n\"إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ وَإِذَا كَانُوا مَعَهُ عَلَىٰ أَمْرٍ جَامِعٍ لَّمْ يَذْهَبُوا حَتَّىٰ يَسْتَأْذِنُوهُ ۚ \nإِنَّ الَّذِينَ يَسْتَأْذِنُونَكَ أُولَٰئِكَ الَّذِينَ يُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِ ۚ فَإِذَا اسْتَأْذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَاسْتَغْفِرْ لَهُمُ اللَّهَ ۚ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ \"\n☆يعني مادام الناس مجتمعين لأمر مهم، مينفعش واحد كده يمشي من دماغه من غير استئذان لأن ده هيأثر على العمل الجماعي كله، والاستئذان ممكن يتقبل وممكن يترفض على حسب رؤية القائد للمصلحة العامة،\nوده مش في الحرب بس يا جماعة ده في أي عمل جماعي\nوصل جابر لبيته ودخل على زوجته وقال لها :\nأنا شفت حاجة مش قادر أستحملها\nأنا شفت الجوع في وجه رسول الله ﷺ فهل عندك أي حاجة أعطيها لرسول الله ﷺ يأكلها\n☆واخدين بالكم إن جابر مع إنه هو كمان كان جائع وبقاله ثلاثة أيام مأكلش إلا إنه كان كل تفكيره وهمه في جوع رسول الله ﷺ \nفزوجته قالت له : عندي صاعٌ من شعير وعندي عَناق\nيعني زي طبق دقيق كده ومعزة صغيرة\nفقال لها اطحني الشعير وجهزيه، وقام هو ذبح العناق وسلخها ونظفها ووضعها في البُرْمة، حاجة زي الحلة الكبيرة عندنا، وده كان كل ما يملكون\nجابر خلص ورايح ينادي على رسول الله ﷺ عشان ييجي يأكل، زوجته وقفته وقالت له:\nإياك أن تفضحني برسول الله ﷺ وإللي معاه\nمفيش أكل، الموجود يادوب يكفي ثلاثة أربعة بالكثير، متروحش تجيبهم كلهم\nجابر رجع لرسول الله ﷺ في الخندق وجه جنب ودنه كده وقال له بصوت واطي:\nيا رسول الله! عندي صاع من شعير وعندي عَناق، فتعال انت وبعض أصحابك\nراح رسول الله ﷺ قايم وبأعلى صوته نادى أهل الخندق:\nيا أهل الخندق تعالوا، جابر عمل لكم طعام\nطبعا جابر اتكسف جدا مش عارف يعمل إيه مفيش أكل\nجاء ألف رجل \nومش أي ألف رجل، دول بقالهم ثلاثة أيام من غير أكل، فتخيلوا جوعهم بقى عامل إزاي\nفقال له رسول الله ﷺ: \nإذهب ولا تخبز ولا تنزل البُرْمة من على النار لحد ما أجيلك\nرجع جابر لزوجته وقال لها: إلحقي رسول الله ﷺ جاي ومعاه أهل الخندق كلهم\nفزوجته قالت له: إنت قلت له إن الأكل قليل ومش هيكفي غير كم واحد\nقال لها : نعم أخبرته\nفقالت له بيقين: الله ورسوله أعلم\nيعني مادام رسول الله ﷺ عمل كده يبقى أكيد هو عارف هو بيعمل إيه،\nوصل رسول الله ﷺ لبيت جابر ومعاه الألف، سأل رسول الله ﷺ فين العجين؟ فجاءوه بالعجين فبَصَق فيه رسول الله ﷺ ودعا بالبركة، وسأل فين البُرمة؟ فدلّوه عليها فبَصَق فيها ودعا بالبركة،\nالبركة من الله ورسول الله ﷺ كان سبب في البركة\nبدأ رسول الله ﷺ يأخذ من الخبز واللحم ويعطي الصحابة،\nوكانوا بيأكلوا عشرة عشرة لحد ما كل الألف أكلوا وشبعوا وتركوا الأكل ومشيوا،\nوالخبز زي ماهو لم ينقص منه شيء والبُرمة فيها اللحم زي ماهو مفيش أي حاجة نقصت\n☆رسول الله ﷺ عمره ما كان هيبقى مبسوط إنه يأكل طعام لوحده وأصحابه بيحفروا وجعانين، رسول الله ﷺ عمره ما أخذ شيء لنفسه فقط والصحابة محتاجين، كان دايما يقدمهم على نفسه،\nحتى لما أكلوا كان هو آخر واحد أكل، كان شخصية كاملة الأوصاف ﷺ، أي حد يقرأ في سيرته غصب عنه هيحبه،\nفما بالكم بالصحابة إللي كانوا عايشين معاه كان حبهم له عامل إزاي، حب لا يمكن وصفه،\nعشان كده الصحابة كانوا بيفكروا فيه أول حاجة قبل ما يفكروا في نفسهم، وكان مُقدم على كل حاجة في حياتهم، \nحب الصحابة لرسول الله ﷺ حب ملوش مثيل فعلا\nومش بس دي المعجزة إللي حصلت، في يوم تاني ابنة أخت عبد الله بن رواحة جاءت بحِفْنة من تمر، يعني كبشة تمر كده عشان تعطيها لأبوها وخالها يتغدوا بها،\nرآها رسول الله ﷺ وهي معدية عليه فطلب منها التمر ووضعه على ثوب فرشه في الأرض ونادى على أهل الخندق،\nجاء الصحابة وبدأوا يأكلوا والتمر يزيد...هم ياكلوا والتمر يزيد،\nلحد ما شبعوا كلهم ومشيوا والتمر بيقع من على طرف الثوب\n☆ممكن حد يفكر إن المعجزات دي خاصة برسول الله ﷺ وبجيل الصحابة فقط،\nلكن الكرامات دي بتحصل دائما وأبدا للصالحين المجاهدين،\nوإللي يقرأ تاريخ المسلمين من بعد رسول الله ﷺ هيلاقي العجب، \nيعني الكرامات مش وقف على رسول الله ﷺ فقط، لكنها حظ من الله ينصر به عباده الصالحين\nالصحابة مستمرين في حفر الخندق، وكان ساعات بعض الصخور بتقف قصادهم مش بيعرفوا يكسروها فكانوا بيستعينوا برسول الله ﷺ عشان يكسرها لهم،\nوهم بيحفروا في يوم واجهتهم صخرة كبيرة، حاولوا يكسروها مفيش فايدة لدرجة إن المَعاول تكسرت وهم بيحاولوا يكسروا الصخرة،\nراحوا لرسول الله ﷺ واشتكوا له، فجاء معهم للمكان إللي فيه الصخرة، ونزل ومسك المِعْول وقال : بسم الله وضرب على الصخرة، فانكسر ثلثها فلما رآها انكسرت قال ﷺ:\nالله أكبر! أُعطيت مفاتيح الشام، والله إني لأُبصر قصورها الحُمر الساعة\nوبعدين ضرب الصخرة ضربة ثانية فانكسر الثلث الثاني وقال :\nالله أكبر! أُعطيت مفاتيح فارس، والله إني لأُبصر قصر المدائن الأبيض\nوبعدين ضرب الجزء الأخير من الصخرة فتفتَّت الصخرة وقال:\nالله أكبر! أُعطيت مفاتيح اليمن، والله إني لأُبصر أبواب صنعاء من مكاني هذا\nرسول الله ﷺ بيبشر المسلمين إنهم هينتصروا على الفرس والروم وأتباعهم في اليمن، وهيملكوا قصورهم ودول أعظم دولتين على وجه الأرض في زمانهم،\nجيش الفُرس لوحده يا جماعة كان أكثر من مليون جندي متخيلين\nوالصحابة قلقانين من العشرة آلاف إللي جايين بعد كم يوم،\nوهم أصلا كلهم ثلاثة آلاف، فاللي هو إزاي يعني يا رسول الله، ده احنا مش لاقيين ناكل، يبقى هننتصر على أعظم دولتين في العالم\nومع ذلك الصحابة صدقوا بوعد رسول الله ﷺ، لأنهم عارفين إنه لا ينطق عن الهوى، وعارفين إن كل كلمة بيقولها هتتحقق، إزاي محدش يعرف، لكن وعد الله هيحصل هيحصل\n☆احنا دلوقتي لو بصينا للواقع بتاعنا هنلاقي إننا أبعد ما نكون عن النصر والتمكين، وكل أعداء الإسلام اجتمعوا على حربه، سواء من الكفار أو المنافقين أو حتى من المسلمين أنفسهم إللي مش فاهمين دينهم صح، وبيضروا الدين وهم مش حاسين ولا عارفين بيعملوا إيه،\nومع ذلك بقول لكم إن المستقبل للإسلام، وإن الإسلام هيرجع يسود تاني وهيكون هو الحاكم الأوحد في الأرض،\nلأن الدين ده بتاع ربنا وهو إللي هيحفظه،\nوأي حد بيحارب الإسلام فهو بيحارب الله، وأي حد بيحارب الله القوي عمره ما هينتصر أبدا، بالعكس ده ربنا هيستعمله هو ذات نفسه لنشر الإسلام ونصرته وتبقى حسرة عليه لما يشوف الإسلام إللي كان بيحاربه بقى هو سبب في انتشاره ونصرته\nانتهى المسلمون أخيرا من حفر الخندق، وهم يادوب خلصوا من هنا ولقوا جيش المشركين وصل على حدود المدينة\nحتى ملحقوش يستريحوا \nيا ترى رد فعل المشركين كان إيه لما شافوا الخندق، وهل قدروا إنهم يعبروا الخندق ولا عملوا إيه\nده إللي هنعرفه الجزء الجاي إن شاء الله \n♡"}, {"n": 118, "l": "الجزء 92 | احداث السنه الخامسه من الهجره | وجاء الأحزاب", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثانية_والتسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#وجاء_الأحزاب\nوقفنا المرة إللي فاتت عند انتهاء الصحابة من حفر الخندق، وهم خلصوا من هنا ولقوا جيش المشركين بكل أحزابه جايين،\nالمشركين لأنهم جمعوا نفسهم من مختلف الطوائف والقبائل بقى اسمهم أحزاب، فاتسمت المعركة دي بغزوة الأحزاب أو غزوة الخندق، والأحداث دي كانت في شوال من السنة الخامسة من الهجرة على أرجح وأصح أقوال العلماء،\nوصل جيش المشركين وشافوا الخندق محفور، وكانت صدمة بالنسبة لهم واتغاظوا جدا\n يعني هم مجمعين الأعداد دي كلها وجايين وعندهم آمال إنهم يقضوا على المسلمين، وفي الآخر ميعرفوش يدخلوا المدينة\nودي أول مرة يشوفوا خندق في حياتهم، هم متعودين على الهجوم والدفاع والمواجهة،\nحتى إنهم قالوا:\nهذه حيلة لا تعرفها العرب\nووقف الجيشان وبينهما الخندق، المشركين مش عارفين يعبروا، مفيش غير طريقين يدخلوا منهم المدينة، \nالطريق إللي أمامهم دلوقتي وطريق تاني من ناحية بني قريظة،\nلكن بني قريظة على عهد مع رسول الله ﷺ،\nفقعدوا يدُورُوا حول الخندق عشان يلاقوا ثغرة يعدوا منها مش عارفين،\nرسول الله ﷺ كان نظّم نقط حراسة على طول الخندق عشان لو حد من المشركين حاول إنه يَعبر الخندق ويهجم على المسلمين يلاقي إللي يرجّعه،\nفكان المسلمون بيرموا المشركين بالسهام عشان محدش منهم يقدر يَعبر الخندق ولا حتى يقدر يردمه ويعدي،\nوبكده كووول العشرة آلاف دول ولا لهم لازمة\nوجعل رسول الله ﷺ مجموعات للقتال، عشان لو حد فلت من السهام وعرف يعدي الخندق يلاقي إللي يُقاتله ويهزمه،\nفكان رسول الله ﷺ عامل حسابه لكل احتمال،\nكان في واحد من فرسان العرب المشهورين اسمه عمرو بن وُدْ وكان معروف بقوته، لدرجة إنه يُقال عنه إنه لو بَارَز أربعين رجل لوحده لنثرهم عن يمينه وشماله،\nالفارس ده قعد رايح جاي على الخندق من أوله لآخره، بيدوّر على أي حتة تكون ضيقة شوية يقدر يعدي منها،\nوفعلا لقى مكان يعتبر ضيق نسبيا فرجع للوراء لعكرمة بن أبي جهل، وضِرار بن الخطاب أخو عمر بن الخطاب وأخبرهم بالمكان،\nفراحوا بالفرس بتاعهم قفزوا مرة واحدة هم الثلاثة من فوق الحتة دي ووصلوا الجهة التانية ناحية المسلمين\nرسول الله ﷺ جهز لهم مجموعة صغيرة من الصحابة يقاتلوهم بقيادة علي بن أبي طالب رضي الله عنه،\nفلما تواجهوا تصدّى علي بن أبي طالب لعمرو بن وُد وقاتله قتال شديد وضربه علي رضي الله عنه بالسيف وقتله،\nوكان علي رضي الله عنه من أقوى الفرسان، ومدخلش مبارزة مع حد إلا وهزمه\nعكرمة بن أبي جهل وضرار بن الخطاب شافوا الفارس عمرو بن ود اتقتل راحوا راجعين على طول\nتكررت محاولات المشركين لعبور الخندق مرات كثيرة، ومنهم محاولة خالد بن الوليد ومعه مجموعة من المشركين إنهم يعبروا، لكن أُسيد بن حُضير ومعاه مئتين من المسلمين قدروا إنهم يمنعوهم،\nالمشركين مش عايزين يستسلموا، وهم عشرة آلاف فكانوا ساعات يضغطوا جامد في الهجوم على الخندق والصحابة يدفعوهم، لدرجة مرة قعدوا يهجموا من قبل العصر لحد بعد المغرب،\n والمسلمين انشغلوا بيهم حتى ضاعت عليهم صلاة العصر، مش لاقيين حتى خمس دقائق يصلوا فيهم تخيلوا كمية الهجوم كانت عاملة إزاي\nوده حدث نادر جدا في السيرة، إن المسلمين يضيع عليهم فرض من الفروض لحد ما يخرج وقته، والمسلمين اتضايقوا جدا إزاي يضيع عليهم صلاة،\nمع إن إللي شغلهم كان الجهاد، مش ماتش كورة، ولا فرجة على فيلم ولا مسلسل ولا...ولا...\nحتى رسول الله ﷺ نفسه قال:\n\"ملأ الله قبورهم وبيوتهم نارا كما شغلونا عن الصلاة الوسطى حتى غابت الشمس\"\nالهجوم ده مقعدش يوم ولا اتنين ولاأسبوع ولا أسبوعين،\nاستمر حصار المشركين للمدينة والهجوم على الخندق شهر كامل، والمسلمين صامدين ثابتين،\nالمشركين كانوا بيرموا المسلمين بالسهام من ناحيتهم فقُتل في غزوة الخندق سبعة من الصحابة،\nوأُصيب سعد بن معاذ رضي الله عنه بسهم في أكحُلِه والأكْحَلِ: هو العِرقُ الَّذي في نِهايةِ القدَمِ،\nأما المشركين فقُتل منهم أربعة،\nأبو سفيان قائد الجيش شاف إن الوضع كده مش نافع، وزي ما المسلمين تعبانين والحصار صعب عليهم كذلك المشركين عندهم نفس المشكلة،\nوزي ما ربنا قال:\n\" إِنْ تَكُونُوا تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ \"\nالحل الوحيد دلوقتي قصاد أبو سفيان وأسهل طريقة لهزيمة المسلمين إن بني قريظة يتعاونوا معاهم وينقضوا العهد مع رسول الله ﷺ،\nوالخطة تكون إن بني قريظة تهجم على المسلمين من خلفهم وهم يهجموا على المسلمين من ناحية الخندق ويردموا منه جزء ويعدوا كلهم وبكده المسلمين هيبقوا بين فكّي كماشة،\nمش هيقدروا يدافعوا عن نفسهم وعن الخندق في نفس الوقت،\nفلو نجحت فعلا الخطة دي، هيقدروا يقضوا على المسلمين نهائيا\nرسول الله ﷺ كان عامل حسابه لاحتمال زي ده، فعشان يكون في الاحتياط ويبقى مطمئن، جمع النساء والأطفال وكبار السن في حصن داخل المدينة،\nعشان محدش يهجم عليهم من أي جهة ويعرضهم للخطر،\nالمشكلة بقى مين إللي هيقنع بني قريظة إنهم يتعاونوا مع جيش المشركين\nطبعا مفيش غير اليهود\nهم قدروا يقنعوا ويجمعوا الأعداد الكبيرة دي من العرب، مش هيقدروا يقنعوا اليهود إللي زيهم\nحُيَي بن أخطب زعيم وفد اليهود قال: أنا هروح اتكلم مع بني قريظة وأقنعهم إنه يدخلونا من ناحيتهم لداخل المدينة، وكمان يساعدونا في الهجوم على محمد وأصحابه وخصوصا إن المدينة فاضية دلوقتي،\nتحرك حُيي بن أخطب وراح فعلا لسيد بني قريظة وكان اسمه كعب بن أسد،\nكعب بن أسد مكنش راضي يقابل حيي بن أخطب، عارف إن مش هييجي من وراه غير كل شر، ماهو شاف إللي حصل لقومه بني النضير، وقبلهم بني قينقاع، فالراجل مش عايز مشاكل،\nلكن حيي بن أخطب مستسلمش، فضل وراه لحد ما وافق يقابله وقال له حُيي:\nجِئُتك بعِز الدهر! جئتك بقريش وسادتها، وغطفان وسادتها، وكلهم عاهدوني إنهم مش هيمشوا غير لما يُبيدوا محمد وأصحابه\nيعني ياعم فرصة ذهبية وجت لك لحد عندك، هنخلص من الراجل ده خالص وإللي معاه، ده أنا لفيت وجمعت لك جيش لا يجتمع، \nفقال له كعب: جئتني والله بذُل الدهر\nسيبني يا حيي زي ما أنا، أنا مشفتش من محمد غير كل صدق ووفاء\nفقال له حُيي :\nطيب شوف أنا هدخل معاك في الحصن بتاعك وهتحمل معاك أي حاجة تحصل لك بعد كده\nومع إلحاح حيي بن أخطب، وافق كعب بن أسد على نقض العهد مع رسول الله ﷺ والتحالف مع جيش المشركين ضد رسول الله ﷺ \nواتفقوا على إن اليهود يفتحوا أبواب المدينة للمشركين، ويجهزوا فِرق عسكرية تهجم على المسلمين من الخلف،\nمتخيلين إللي هيحصل لرسول الله ﷺ والصحابة\nعشرة آلاف من الأمام وعلى أقل تقدير سبعمائة مقاتل من الخلف، لو حصلت فعلا الخطة دي كل إللي في المدينة هيُقتلوا مش هيبقى فيها حد على قيد الحياة\nرسول الله ﷺ كان خايف وقلقان من خيانة اليهود، هو مكنش يعرف المستقبل، ومكنش عنده وحي بشيء يعني كبشر لازم هيقلق ويخاف،\nلكن الفرق بين رسول الله ﷺ والذين اتبعوه على نفس المنهج وبين الناس التانية إن رسول الله ﷺ على الرغم من قلقه وخوفه فهو بياخد احتياطاته كويس\nعشان كده كان حاطط مجموعة يراقبوا تحركات بني قريظة،\nلاحظت المجموعة تحركات غريبة في بني قريظة فعرفوا إن القوم نقضوا العهد،\nأرسلوا الخبر لرسول الله ﷺ، وقبل ما رسول الله ﷺ يأخذ أي قرار أراد إنه يتأكد إذا كانوا فعلا غدروا ونقضوا العهد ولّا لأ،\nفأرسل رسول الله ﷺ مجموعة من الصحابة عشان يتأكدوا وكان فيهم سيّدا الأنصار سعد بن معاذ وسعد بن عبادة،\nوقال لهم: \nروحوا شوفوا بني قريظة هل فعلا نقضوا العهد ولّا لأ، فلو كانوا فعلا نقضوا العهد متعلنوش ده للناس عشان ميجلهمش إحباط وقولوا لي حاجة أفهم بها إنهم نقضوا العهد،\nلكن لو لقيتوهم لسه على العهد فأعلنوا للناس إنهم على العهد\n☆يعني منهج رسول الله ﷺ إن الأخبار السيئة يخفيها عن الناس، لكن دلوقتي عامة المسلمين ينشروا أخبار وخطط وتسليحات أعداء الإسلام في كل مكان لحد ما يكون الإحساس السائد إن مفيش فائدة ومفيش أي أمل\nرسول الله ﷺ بيعلمنا إن 《ليس كل ما يُعرف يُقال》\nتخيلوا لو طبقنا القاعدة دي في حياتنا العملية دلوقتي هنتجنب مشاكل أد إيه وهنتجنب غيبة ونميمة أد إيه\nوصلت المجموعة لبني قريظة وسألوهم هل لازلتم على العهد مع رسول الله ﷺ؟\nفبني قريظة جهروا بالسوء وشتموا الصحابة وشتموا رسول الله ﷺ، وقالوا مفيش بيننا أي عهد،\nرجع الصحابة لرسول الله ﷺ وقالوا له :\n《عَضُل والقَارة》\nفاكرينهم؟\nالقبائل إللي غدرت بالصحابة وقتلوهم، فهم بيقولوا لرسول الله ﷺ بني قريظة غدروا زي ما غدرت عضل والقارة،\nفحزن رسول الله ﷺ حزنا شديدا، وقعد يفكر إيه إللي هيحصل، إللي ينظر للحالة يقول خلاص المسلمين انتهوا\nوفجأة قال لهم بصوت عالي:\nالله أكبر أبشروا بالنصر\nلكن خبر غدر بني قريظة انتشر وسط المسلمين بالرغم من محاولات رسول الله ﷺ لإخفاء الخبر،\nلكن ده قدر وحكمة ربنا، عشان يزلزل المسلمين ويظهر كل واحد على حقيقته ومين فعلا إللي هيثبت في الموقف الرهيب ده،\nإللي فات كله من الابتلاءات كان حاجة والابتلاء دلوقتي حاجة تانية خالص، \nمحدش هيثبت هنا غير صادق الإيمان، منين رسول الله ﷺ كان بيبشرهم بإنهم هيهزموا أعظم دولتين على وجه الأرض ودلوقتي هم معرضين للإبادة الكاملة\nفكان المنافقين يقولوا: \n\"وَإِذْ يَقُولُ الْمُنَافِقُونَ وَالَّذِينَ فِي قُلُوبِهِم مَّرَضٌ مَّا وَعَدَنَا اللَّهُ وَرَسُولُهُ إِلَّا غُرُورًا \"\nيعني كانوا بيضحكوا علينا ومفيش نصر ومفيش تمكين ولا أي حاجة، وبدأوا يتسربوا وينسحبوا من أرض المعركة ويتحججوا إن بيوتهم عورة، يعني معلهاش حراسة وممكن أي حد يهجم عليهم،\nلكن ده كان حجة بس عشان يهربوا زي ما ربنا قال:\n\"وَيَسْتَأْذِنُ فَرِيقٌ مِّنْهُمُ النَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌ وَمَا هِيَ بِعَوْرَةٍ ۖ إِن يُرِيدُونَ إِلَّا فِرَارًا \"\nالمسلمين حالهم صعب جدا، ربنا بيوصفهم:\n\"إِذْ جَاءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ الْأَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا ۩ هُنَالِكَ ابْتُلِيَ الْمُؤْمِنُونَ وَزُلْزِلُوا زِلْزَالًا شَدِيدًا\"\nمرحلة الزلزلة دي أشد مراحل الابتلاء، لكن معنى إنها جت والإنسان ثبت يبقى خلاص النصر قريب جدا\n\"وَزُلْزِلُوا حَتَّىٰ يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتَىٰ نَصْرُ اللَّهِ ۗ أَلَا إِنَّ نَصْرَ اللَّهِ قَرِيبٌ\"\nرسول الله ﷺ قائد عملي، لازم يشوف حل للمشكلة دي، وإلا المسلمين كلهم هيبادوا بما فيهم الأطفال والنساء\nيا ترى رسول الله ﷺ عمل إيه عشان يحل الأزمة دي؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 119, "l": "الجزء 93 | أحداث السنه الخامسه من الهجره | هزيمة الأحزاب", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_الثالثة_والتسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#هزيمة_الأحزاب\nاتكلمنا المرة إللي فاتت عن نقض بني قريظة العهد مع رسول الله ﷺ واتفاقهم مع قريش في الهجوم على المسلمين،\nرسول الله ﷺ كان لازم يشوف حل للأزمة دي،\nلكن أول حاجة رسول الله ﷺ فكّر فيها قبل ما يأخذ أي قرار إنه يرسل مجموعة من المقاتلين لحماية النساء والأطفال وكبار السن إللي كانوا في الحصن داخل المدينة،\nلأنه كان أخذ معاه كل المقاتلين عشان يدافعوا عن الخندق والمدينة بقت فاضية، على اعتبار إن بني قريظة على العهد،\nلكن الوضع دلوقتي اتغير وأول حاجة ممكن اليهود يعملوها إنهم يهجموا على النساء والأطفال فكان لازم لهم حماية،\n☆في رواية مشهورة بتقول إن في واحد من اليهود راح ناحية الحصن إللي فيه النساء عشان يستكشف الخبر فرأته صفية بنت عبد المطلب عمة رسول الله ﷺ فأخذت عمود وضربته على رأسه، فخاف اليهود وقالوا أكيد الحصن مليان بالمقاتلين،\nالقصة دي \nضعيفة لا تصح \nرسول الله ﷺ عايز يكسر التحالف ده بين قبيلة غَطَفان واليهود وقريش،\nففكر إنه يَعرض على غطفان عرض مادي،\nواختار غطفان بالذات؛ لأن قريش يستحيل تقبل بالمال مقابل إنهم يرجعوا؛ لأن المعركة بين قريش وبين رسول الله ﷺ معركة عقيدة\nواليهود برده مش هينفع نغريهم بالمال؛ لأن هم أصلا عندهم أموال كثيرة وبيكرهوا المسلمين جدا وبيحقدوا عليهم،\nده غير إن التعاهد معهم غير مضمون كل شوية ينقضوا العهود، \nوربنا قال عنهم:\n\"أَوَكُلَّمَا عَاهَدُوا عَهْدًا نَّبَذَهُ فَرِيقٌ مِّنْهُم ۚ بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ \"\nفمش فاضل غير غَطفان هي إللي ينفع نغريها بالمال،\nواحنا عارفين إن السبب إللي أغرى غطفان للتحالف مع اليهود وييجوا يقاتلوا معاهم إن اليهود وعَدُوهم بثمار خيبر لمدة سنة،\nفلو رجعت غطفان إللي عدد مقاتليها ستة آلاف يبقى كده رجّعنا أكثر من نصف الجيش\nفاجتمع رسول الله ﷺ مع زعماء غطفان عُيَيْنة بن حصن والحارث بن عوف، إزاي وصل لهم رسول الله ﷺ وتقابلوا\nإزاي الله أعلم\nكتب التاريخ مذكرتش إزاي حصل الترتيب للقاء ده، لكن واضح إنها كانت فرصة سريعة لدرجة إن رسول الله ﷺ ملحقش يقول لكبار الصحابة ولا حتى يُشرك حد منهم معاه في الإجتماع ده، إللي يهمنا في الموضوع إن رسول الله ﷺ اجتمع معاهم،\nحصل بينهم مشاورات ومداولات طويلة، كانت النتيجة النهائية إنهم اتفقوا إن جيش غطفان يرجع ويفك الحصار عن المسلمين بشرط إنهم يأخذوا ثلث ثمار المدينة لمدة سنة كاملة،\nلكن رسول الله ﷺ ميقدرش يكمل في الإتفاق غير لما يستشير أصحابه وخصوصا سيدا الأوس والخزرج سعد بن معاذ وسعد بن عبادة؛ لأن رسول الله ﷺ وإن كان هو رئيس المدينة لكن الثمار دي مش بتاعته دي بتاعة أهل المدينة من الأوس والخزرج وهمّ إللي لازم يقرروا، \nمع إنه لو قال لهم أنا اتفقت على كذا وخلاص ونفذوا محدش فيهم هيعترض لكن رسول الله ﷺ بيعلمنا يعني إيه احترام الملكية الشخصية للأفراد،\nبيعلمنا يعني إيه : لا يَحل مالِ امرئٍ مسلم إلا عن طيبِ نفس منه، \nطبعا احنا بنتكلم في أمور الحياة العادية إللي رسول الله ﷺ بيجتهد فيها برأيه مش أوامر عن طريق الوحي\nاجتمع رسول الله ﷺ مع سعد بن معاذ وسعد بن عبادة وحكى لهم على الإتفاق إللي كان بينه وبين غطفان، \nوهو كان مفكر إن ده عرض مغري جدا هيُخرِج المدينة من الأزمة دي وهيقبل به سيدا الأنصار وخصوصا إن التفاوض ده حصل بعد شهر كامل من الحصار، يعني خلاص الكل تعبان ونفسهم يخلصوا من الحصار ده،\nسعد بن معاذ وسعد بن عبادة قبل ما يردوا بالموافقة أو الرفض سألوا رسول الله ﷺ:\nيا رسول الله! هل الاقتراح ده انت عايزه وحابه، ولّا هو أمر ربنا أمرك به، ولّا انت بتعمل كده مضطر عشان نطلع من الأزمة دي؟\n☆واخدين بالكم من فِهم الصحابة \nهم عندهم القاعدة واضحة، لو رسول الله ﷺ حابب كده أو ده أمر من عند ربنا خلاص هنسمع ونطيع من غير ما يكون لنا رأي ولا حتى هنعترض، لكن لو كان رأي بشري فاحنا ممكن نقول رأينا، وده إللي لازم نتعلمه\nإيه الفرق لما ييجي لنا أمر من رسول الله ﷺ مباشر وبين إنه ييجي لنا الأمر عن طريق حد، الأمر هو هو، ليه بقى لازم ندخل عقلنا في كل حاجة ونقول لازم نتقتنع الأول\nيا جماعة احنا بنعبد ربنا مش بنعبد عقلنا\nولو في حكمة من الأمر ممكن نتعلمها عادي عشان نثبّت الإيمان في قلوبنا، لكن الأصل إننا ننفذ أوامر ربنا بدون أي نقاش\nرسول الله ﷺ رد عليهم وقال لهم:\nلأ، أنا بعمل كده مضطر عشانكم، أنا موافقتش على الاقتراح ده غير لما لقيت العرب كلهم اجتمعوا عليكم عشان يُبيدوكم، فقلت أكسر تحالفهم وأبعدهم عنكم!\nفقال سعد بن معاذ:\nيا رسول الله! لما كنا احنا والناس دي على الشرك وعبادة الأوثان ولا نعبد الله ولا نعرفه؛ محدش فيهم كان يطمع إنه يأخذ ثمرة واحدة من المدينة إلا بالبيع أو الضيافة،\nفلما دلوقتي ربنا أكرمنا بالإسلام وهدانا به وبقينا أعِزة به وبك، نعطيهم أموالنا كده بكل بساطة\nلأ مش عايزين، والله ما يأخذوا منا غير السيف حتى يحكم الله بيننا وبينهم\nفأُعجب رسول الله ﷺ برأي سعد بن معاذ، مع إنه كان مخالف لرأيه ﷺ وقال له: أنت وذاك، يعني خلاص انت حر،\nوأرسل رسول الله ﷺ إلى زعماء غطفان وقال لهم عن رفض سيدا الأوس والخزرج للمفاوضات بينهم،\n☆ممكن حد يقول : يعني هو خلاص حبكت، ما كانوا يتنازلوا وخلاص ويفكوا الحصار بدل ما كلهم هيموتوا دلوقتي أهم\nشوفوا، \nديار غطفان قريبة من المدينة، فأهل المدينة عارفينهم وعارفين طبعهم حتى قبل الإسلام، المشكلة مش في صَرف ثلث ثمار المدينة،\n المشكلة إن كده غطفان هتبقى حققت انتصار غير مقبول على الدولة الإسلامية، وصورة الدولة الإسلامية هتهتز قصاد غطفان وقصاد كل الجزيرة العربية، \nويبقى كده فتحنا باب لابتزاز المسلمين، وخصوصا إن غطفان مش ناس أشراف نُبلاء، دول مرتزقة مَأْجورين،\nفكل ما هيبقوا عايزين أموال هييجوا يحاصروا المدينة، وبدل ما كان هيبقى حصار واحد ونخلص منه، هيبقى كل شوية حصار من هنا ومن هنا ومش هنخلص\nلكن الوقفة الصلبة الجريئة دي هتهز غطفان إللي مش بيفكروا غير في الأموال والدنيا فقط وتخليهم يضعفوا أمام المسلمين، لأن طالب الدنيا ضعيف أمام طالب الآخرة\nفكان قرار سيدا الأنصار في منتهى الحكمة وبُعد النظر\nوحتى رسول الله ﷺ أقرّه على رأيه، ولو كان في خطأ كان هيوقفه، \nوعلى فكرة، الوحي كان ممكن ينزل ويخلّص الموضوع كله ويقول إن الرأي الصحيح هو كذا وخلاص خلصنا،\nلكن ربنا بيعلمنا الشورى بطريقة عملية، بيورينا إزاي الواحد ممكن يغير رأيه وياخد برأي غيره مادام الرأي التاني هو إللي فيه المصلحة وبيفتح الباب للناس إنهم يفكروا ويُعرضوا رأيهم بغض النظر عن مكانتهم،\nهو في حد زي رسول الله ﷺ، طبعا لأ \nومع ذلك رسول الله ﷺ أخذ برأي مخالف لرأيه ﷺ من حد أقل منه في المنزلة لأن كان فيه المصلحة\nرجع سعد بن معاذ للدفاع عن الخندق وأُصيب بسهم في قدمه زي ما قلنا قبل كده وكانت إصابة خطيرة وكأن الله يريد أن يختبر صدق كلام سعد،\nيعني هو كان بإيده ينهي الحصار بإنه يتنازل عن ثلث ثمار المدينة، فهل هيستمر على موقفه لله، ولّا هيندم ويقول ياريتني كنت دفعت الفلوس وحافظت على حياتي؟\nسعد بن معاذ إللي كان عمره في الوقت ده سبعة وثلاثين عام قال: \nاللهم إنك تعلم أنه ليس أحدٌ أحب إليّ أن أُجاهده فيك مِن قومٍ كذّبوا رسولك وأخرجوه، \nفلو كان بقيَ حرب بين قريش وبين نبيك فأبقني لهم حتى أُجاهدهم فيك، \nولو كانت الحرب خلاص انتهت فافجرها، يعني افجر إصابتي واجعلها تزيد- واجعل موتتي فيها، ولا تُمتني حتى تَقر عيني من بني قريظة\nالأزمة وصلت لأعلى درجة، سيد الأوس الفارس الشجاع أُصيب إصابه شديدة، ومتوقعين هجوم بني قريظة في أي لحظة ومعاهم هجوم الأحزاب من ناحية الخندق،\nمحدش ثابت في الموقف ده غير المؤمنين الصادقين، \nالمنافقين هربوا خلاص، \nالصحابة عملوا كل إللي في إيدهم، حفروا الخندق واستحملوا الخوف والجوع وقاتلوا وحموا الخندق بأرواحهم وسهروا وتعبوا وعملوا مفاوضات، خلاص مبقاش في حاجة في إيدهم تاني يعملوها،\nكل أسباب النصر بذلوها، حتى الدعاء، مبطلوش دعاء كانوا يقولون:\n\"اللهم استر عوراتنا وآمن روعاتنا\"\n وهم عارفين إن النصر بيد الله وإنه قادر ينصرهم في أي وقت، محدش منهم اعترض وسأل هو ليه ربنا منصرناش لحد دلوقتي، هم عارفين إن لازم الصبر ولازم التميبز بين الخبيث والطيب\nحتى رسول الله ﷺ كان بيدعو ويقول:\n\"اللهم مُنزلَ الكتاب، سريعَ الحساب، اهزم الأحزاب، اللهم اهزمهم وزلزلهم\"\nمن سنن ربنا الكونية إن لما الابتلاء يشتد لدرجة إن الإنسان خلاص ييأس ويبقى مش شايف قصاده أي حل، يلاقي ربنا أرسل له الفرج وحل له المشكلة من باب عمره ما كان يتخيله،\nوهو ده إللي حصل هنا\nبنو قريظة أرسلوا لأبي سفيان يطلبوا منه إنه يبعث لهم رجالا من جيشه يساعدوهم في الهجوم على رسول الله ﷺ من الخلف، وفي نفس الوقت جيش الأحزاب يهجم معاهم من ناحية الخندق وبكده يقضوا على جيش المسلمين مرة واحدة،\nسمع الكلام ده واحد من قبيلة غطفان اسمه نُعيم بن مسعود، وكان أسلم ومحدش يعرف بإسلامه،\nفجاء لرسول الله ﷺ وقال له : يا رسول الله، إني أسلمت وقومي ميعرفوش إني أسلمت، وأخبره بخطة بني قريظة مع أبي سفيان إللي سمعها،\nفقال له رسول الله ﷺ إن هو إللي طلب من بني قريظة إنهم يطلبوا رجال من أبي سفيان وأول ما يوصلوا عندهم يقتلوهم\nعلى أساس يعني إنهم ندموا على نقض العهد مع رسول الله ﷺ فعايزين يصلحوا غلطتهم فهيقتلوا المجموعة دي عشان يثبتوا حسن نيتهم لرسول الله ﷺ، \nهو ده محصلش، لكن عشان الكلام يوصل لجيش المشركين،\n☆طبعا احنا اتكلمنا قبل كده وقلنا إن الحرب خُدعة، وإن الكذب أصلا جائز وقت الحرب\nنعيم بن مسعود رضي الله عنه كان في صفة غالبة عليه وهي صفة نقل الكلام يعني،\n هو لسه مسلم قريب فلسه أخلاق الجاهلية فيه ولم يتأدّب بأداب الإسلام ورسول الله ﷺ كان عارف عنه الصفة دي،\nفهو لما سمع الكلام ده من رسول الله ﷺ مقدرش يمسك نفسه، وغلبت عليه عادته فرجع لأبو سفيان وقال له كلام رسول الله ﷺ، فقال أبو سفيان :\nصدق والله محمد، ما كذب قط\nولم يرسل لهم أبو سفيان حد وعرف كده إن بني قريظة خدعوه، فنشأت الفُرقة بين يهود بني قريظة وبين جيش الأحزاب،\n☆القصة المشهورة بين الناس وحتى في مشايخ بيقولوها عن نعيم بن مسعود ودوره في غزوة الخندق غير القصة إللي أنا حكيتها، القصة إللي أنا حكيتها هي القصة الصحيحة، وممكن تراجعوا كتاب :\n《ما شاع ولم يثبت في السيرة النبوية》\n ،\nفمش معنى إن في قصة مشهورة والناس بتنقلها يبقى هقولها حتى لو كانت ضعيفة أو لا تصح،\nأنا معتمدة على الأحاديث الصحيحة فقط في حكاية السيرة\nربنا أرسل ريح شديدة جدا باردة على معسكر المشركين، مسابتش خيمة إلا وقلعتها، ولا قِدْر إلا وقلبته، ولا نار إلا وأطفأتها، كل ده ورسول الله ﷺ في الناحية التانية من الخندق ميعرفش إيه إللي بيحصل،\nكان في برد وريح عند المسلمين لكنها كانت هيّنة بالنسبة للي بيحصل للمشركين، \nرسول الله ﷺ كان عايز يعرف إيه إللي حصل للمشركين، فقال لأصحابه وكان الوقت ليل: \nمن فيكم يروح يشوف خبر الجيش وأضمن له إنه يرجع وهو رفيقي في الجنة؟\nفمحدش قام من الصحابة \nرسول الله ﷺ ضامن للي هيروح يشوف الخبر إنه يرجع وكمان هيدخل الجنة، ومع ذلك محدش قام\nعشان تتصوروا شدة الخوف والجوع والبرد إللي كان فيها الصحابة كانت عاملة إزاي \nرسول الله ﷺ أعاد الكلام مرة ثانية ومحدش قام، وأعاده مرة ثالثة محدش قام\n☆في ناس تقعد تتمنى وتقول ياريتني كنت موجود في عصر رسول الله ﷺ، كنت هدافع عنه وكنت صدقه، وكنت ...وكنت...مين قال إن إللي بيتمنى ده كان هيبقى فعلا مؤمن برسول الله ﷺ،\nأهل مكة كانوا بيقولوا على رسول الله ﷺ الصادق الأمين وبعد الرسالة كذبوه،\nفليه نتمنى مشهد ربنا غيّبنا عنه؛ الله أعلم لو كنا فيه كنا هنبقى إيه، وهل كنا هنبقى من المُصدقين ولّا من المكذبين،\nفالأحسن إننا نحمد ربنا على إنه أخرجنا من بطون أمهاتنا لا نعرف إلا الإسلام،\nطبعا الاشتياق لرؤية رسول الله ﷺ دي حاجة تانية مفيهاش حاجة\nلكن الكلام هنا على إننا نتمنى إننا كنا في عصر رسول الله ﷺ؛ لأن زي ما شفنا دلوقتي أهه، رسول الله ﷺ بيوعد الصحابة بالجنة ويوعد إن إللي هيروح هيرجع تاني سليم  ومع ذلك محدش قام،\nاحنا بنشوف في عصرنا دلوقتي الناس بتتخلى عن مبادئها وساعات كتير عن دينها بسبب الفقر وإنها خايفة على لقمة العيش،\nفتخيلوا بقى الصحابة بقالهم شهر تحت الحصار تعبانين جدا من الدفاع عن الخندق ومن قبلها حفر الخندق، ده غير الجوع وشدة البرد ده غير القلق النفسي إن بني قريظة ممكن يهجموا عليهم في أي لحظة،\nفي ناس في عصرنا مش بتقدر تقوم تصلي الفجر في البرد مع إنها هتتوضى بمية سخنة، وهيبقوا لابسين ملابس ثقيلة، \nتخيلوا لو كانوا في عصر رسول الله ﷺ كانوا هيبقوا عاملين إزاي\nرسول الله ﷺ لما لقى إن محدش قام؛ نادى على حذيفة بن اليمان رضي الله عنه، فمكنش قصاد حذيفة حل غير إنه يستجيب لنداء رسول الله ﷺ لأنه طلبه بالاسم يعني الموضوع مبقاش فيه اختيار ده بقى أمر لازم\nقال له رسول الله ﷺ :\nروح شوف لي خبر الجيش وعملوا إيه وتعال قول لي، ولا تُذعرهم علينا\nيعني متعملش حاجة تخليهم يثوروا علينا أو متعملش حاجة لحد ما ترجع، يعني هو عايز بس يعرف أخبار الجيش مش أكثر،\nفأول ما مشي حذيفة من عند رسول الله ﷺ حس كأنه في حمّام، وانتم عارفين إن الحمام بيبقى دافئ،\nيعني الجو حوله برد بس هو مش حاسس بالبرد، يعني ربنا هوّن عليه المهمة الصعبة دي لأنه أطاع أمر رسول الله ﷺ \nيا جماعة مهما كانت أوامر ربنا في ظاهرها صعبة وإني مش هقدر عليها، مجرد ما الإنسان يَمتثِل لأمر ربنا وييجي على نفسه وينفذه، ربنا هيكون في عونه ويساعده،\nزي حذيفة بن اليمان كده، هو مش كان ممكن يعتذر بأي عذر لرسول الله ﷺ ويقول له شوف حد غيري يا رسول الله\nلكن هو معملش كده هو قاوم وسمع كلام رسول الله ﷺ فربنا هوّن عليه المهمة وشال من عليه البرد\nخليكم دايما فاكرين قصة حذيفة بن اليمان عشان لما ييجي لكم الأمر من الله ورسوله وانتم مستصعبينه اضغطوا على نفسكم ونفذوا، هتلاقوا ربنا هوّن عليكم وخفف عليكم المشقة\nوصل حذيفة لمعسكر المشركين ولقى الريح عندهم شديدة جدا مش مخلية حاجة في مكانها، يعني تقريبا زي العواصف إللي بنشوفها كده في التليفزيون\nدخل حذيفة وسط الناس لقى أبو سفيان جامع الناس بيكلمهم فقعد حذيفة وسطهم فقال لهم أبو سفيان :\nكل واحد يشوف ويتأكد مين إللي جنبه\nلأن الدنيا كانت ضلمة ساعتها ومفيش نار متقادة، فعشان يتأكد إن مفيش حد دخل بينهم قال لهم يتأكدوا من بعض،\nكده حذيفة اتورط، هيتكشف\nفربنا ألهمه بفكرة، وبسرعة حط إيده على يد الرجل إللي على يمينه وقال له : انت مين؟ \nفقال له : فلان بن بن فلان، وسأل إللي على شماله : انت مين؟\nفقال له : فلان بن فلان، ومحدش سأله هو مين \nوزي ما بنقول، أفضل وسيلة للدفاع هي الهجوم\nأبو سفيان قال لهم:\nيا معشر قريش! \nانتم شايفين إللي بيحصل، مش هينفع نقعد هنا أكثر من كده، وكمان بلَغنا من بني قريظة ما نكرهه، ومفيش حاجة \nبتثبت على حالها، الخيام بتتقلع والقدور بتتقلب، \nفأنا راجع لمكة فارجعوا، وقام ركب على جمله واتجه ناحية مكة وباقي جيش مكة وراه،\nيقول حذيفة : لولا كلام رسول الله ﷺ إني معملش حاجة لحد ما أرجع كنت ضربته بالسهم وقتلته\nلكن لأن رسول الله ﷺ قال له متعملش حاجة لحد ما ترجع فهو سمع كلام رسول الله ﷺ وترك أبو سفيان يمشي،\nوجيش غطفان لما عرف انسحاب قريش، انسحبوا هم كمان لبلادهم، وانهزم الأحزاب وخلصت المعركة، بس كده\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَاءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا ۚ وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا \"\n☆ممكن حد يقول طيب ما كان ربنا أرسل عليهم الريح دي من الأول وخلصنا، بدل التعب ده كله\nماهو نصر ربنا يا جماعة مش بييجي كده لأي حد، النصر لا يأتي إلا للمؤمنين الصادقين، فلازم الابتلاء عشان يتميز الصادق من الكاذب والمؤمن من المنافق\nرجع حذيفة بن اليمان بالخبر الجميل والنصر العظيم لرسول الله ﷺ، جاء لرسول الله ﷺ وكان يصلي، فقعد جنبه لحد ما خلص صلاة وأخبره بالخبر،\n\"وَرَدَّ اللَّهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ لَمْ يَنَالُوا خَيْرًا وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللَّهُ قَوِيًّا عَزِيزًا\"\nوانتهت واحدة من أعظم معارك المسلمين، مع أنه محصلش فيها قتال زي غزوة بدر أو غزوة أحد،\n وكأن الله عز وجل يريد أن يقول لنا:\n مش مطلوب تحقيق النصر، أو تحقيق أي نتيجة ولكن المطلوب هو الأخذ بالأسباب وبذل المجهود ، \nالنصر أو النتيجة بتاعة ربنا، مطلوب مننا نأمر بالمعروف وننهى عن المنكر مش مطلوب مننا إننا نخلي الناس تستجيب لنا وتسمع الكلام،\nربنا يا جماعة هيحاسبنا على إللي نقدر نعمله، وهل قصرنا ولّا لأ، مش هيحاسبنا على النتيجة أبدا، النتيجة أو النصر هينزل بالطريقة التي يريدها الله عز وجل، وفي الوقت الذي يريد سبحانه وتعالى\nرجع رسول الله ﷺ من الخندق لبيته ورجع الصحابة، خلاص انتهت غزوة الأحزاب، دخل بيته ﷺ يغتسل بعد غياب شهر وبعد مشقة وعناء، \nلكن......\nلكن إيه \nده إللي هنعرفه الجزء الجاي إن شاء الله \n♡"}, {"n": 120, "l": "الجزء 94 | احداث السنه الخامسه من الهجره | غزوة بني قريظه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_الرابعة_والتسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#غزوة_بني_قريظة\nاتكلمنا المرة إللي فاتت عن نهاية غزوة الأحزاب ورجوع المشركين لديارهم، بعد ما مشيوا رسول الله ﷺ قال للصحابة :\nاليوم نغزوهم ولا يغزونا\nيعني من بعد النهاردة قريش مش هتيجي تقاتلنا مرة ثانية، واحنا إللي هنروح نقاتلهم،\nجيش المشركين أكيد أصابه اليأس، بعد ما جمعوا الأعداد الكبيرة دي ومقدروش على هزيمة المسلمين، هيعملوا إيه تاني\nرجع رسول الله ﷺ لبيته بعد انتهاء المعركة، لكن هل فعلا انتهت المعركة\nجاء جبريل عليه السلام لرسول الله ﷺ في صورة رجل وفي رواية إنه كان على صورة واحد من الصحابة اسمه دِحية الكلبي، فجاءه وكان بيغتسل فقال له:\nيا محمد! هل وضعت سلاحك؟ \nفإن الملائكة لم تضع أسلحتها\nيعني جبريل عليه السلام بيقول لرسول الله ﷺ إن الحرب لسه منتهتش، ده لسه المعركة مستمرة، فسأله رسول الله ﷺ: فين؟!\nفأشار جبريل عليه السلام لديار بني قريظة، \nبني قريظة إللي بخيانتهم عرّضوا المسلمين للإبادة،\nكان بقالهم خمس سنين محافظين على العهد مع رسول الله ﷺ، ودلوقتي أول ما جاءت لهم الفرصة نقضوا العهد،\nإزاي هنقدر نسيبهم في المدينة بعد كده وكأن شيئا لم يكن،\nالطابور الخامس ده لازم نتخلص منه، وإلا هيخوننا مرة واثنين وثلاثة كل ما جاءت له الفرصة وهيطعن المسلمين في ظهورهم\nفنادى رسول الله ﷺ في المسلمين وقال:\nمن كان سامعاً مطيعاً فلا يُصلّيَنّ العصر إلا في بني قريظة\nوالكلام ده كان بعد الظهر ، وبني قريظة داخل المدينة يعني هي حي من أحياء المدينة لكنها بعيدة فمحتاجة وقت على ما يوصلوا لها،\nفرسول الله ﷺ بيستعجلهم لأن على ما يتجمعوا فيها وقت، فمكنش عايز حد يتأخر أو ياخد راحته وهو بيتجهز،\nجبريل عليه السلام انطلق مع الملائكة لديار بني قريظة وتجمع المسلمون وانطلقوا مع رسول الله ﷺ لديار بني قريظة،\nوالملائكة قاتلت المشركين في غزوة الأحزاب، ربنا بيقول:\n\"فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَمْ تَرَوْهَا \"\nحصل بين الصحابة اختلاف، في مجموعة حسوا إن العصر هيفوتهم فصلوه في الطريق لبني قريظة وقالوا رسول الله ﷺ أراد إنه يستعجلنا،\nومجموعة تانية قالوا لأ رسول الله ﷺ قال محدش يصلي العصر غير في بني قريظة فمصلوش غير في بني قريظة ولكن كان على آخر وقت العصر، \nفلما وصلوا لبني قريظة وقالوا لرسول الله ﷺ؛ أقر كل مجموعة على فعلها على حسب ما فهموا من ظاهر كلام رسول الله ﷺ.\nوصل رسول الله ﷺ والملائكة لحصون بني قريظة، لكن رسول الله ﷺ اختار المكان المناسب إللي هيخيم فيه الجيش، \nهو مش هيقعد في أي مكان كده وخلاص، ده لازم ترتيب\nلأنه عارف إن المسالة فيها حصار، وهياخد وقت لأن بني قريظة كانوا داخل حصون، \nيعني مكان له بوابات وأسوار مش مجرد إنه هيقعد يوم وتاني يوم يقول يلا هجوم ويخلص المعركة، الموضوع هياخد وقت،\nفنزل حول بئر ماء،\nدخل بنو قريظة حصونهم وقفلوا الأبواب عليهم والمسلمون خارج الحصون،\nوهم عندهم أكلهم وماءهم داخل الحصون يعني مش هيحتاجوا يخرجوا لأي سبب\nتخيلوا إن رسول الله ﷺ هيحاصر بني قريظة خمسة وعشرين يوم والدنيا برد ولسه حالة الفقر مستمرة\nيعني هم لسه طالعين من حصار شهر وتعبانين وملحقوش يستريحوا وطلعوا لحصار تاني قريب من الشهر برده، لكن شوفوا العبرة هنا، الآية اتقلبت\nبعد ماكانوا مُحاصَرين مستضعفين خايفين من الهجوم عليهم بقوا هم دلوقتي إللي بيحاصروا إللي كانوا هيجموا عليهم، سبحانه مغير الأحوال\nلكن المشكلة دلوقتي بقى إزاي هيحصل قتال\nبنو قريظة داخل حصونهم عندهم أكلهم وشربهم ونايمين في بيوتهم، والمسلمين برة قاعدين في برد ومعندهمش أكل وتعبانين،\nإللي ينظر للموقف هيلاقي إن الكفة بتميل ناحية بني قريظة والمسلمون المفروض إنهم هيزهقوا ويرجعوا، لكن هنا في المواقف إللي زي كده تأتي رحمة الله،\nالمسلمين عملوا إللي عليهم خططوا ورتبوا وحاصروا...بذلوا كل الأسباب إللي يقدروا عليها، ربنا بقى بيوفي بوعده للمؤمنين، مش ربنا بيقول:\n\"وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ\"\nالصحابة مع رسول الله ﷺ حققوا الإيمان الكامل وبذلوا الأسباب فهنا يأتي النصر،\nربنا قذف الرعب في قلوب اليهود، أصل القلوب دي بين يدي الله يُقلبها كيف يشاء،\nوإللي مفكر إنه بشطارته ممكن ينتصر أو يكسب قلوب الناس أو يخوّفهم منه يبقى غلطان، ده ربنا هو إللي بيلقي المحبة أو الرعب في قلوب الناس\nبنو قريظة عايشين في رعب من رسول الله ﷺ مع إن إللي يشوف الموقف يقول إن مفيش أي داعي للخوف خالص،\nده هم إللي منتصرين، لكن رب العالمين إذا أراد شيئا فإنما يقول له كن فيكون\nكعب بن أسد زعيم اليهود من شدة خوفه جمع اليهود وقال لهم : أنا هديكم ثلاثة اختيارات اختاروا منهم واحد:\n◇الأول: \nإما أن تُسلموا وتعصموا دماءكم وأموالكم، وانتم شوفتم إن محمد هو نبي آخر الزمان وهو إللي موجود وصفه عندكم في التوراة\nفقالوا: لأ طبعا، نسلم إيه ونترك دين اليهود\n◇فقال لهم الثاني:\nخلاص تقتلوا بأيديكم نساءكم وأبناءكم وتخرجوا على محمد مرة واحدة وتحاربوه وتُقاتلوه،\nفلو انتصرتم انتصرتم ولو قُتلتم مفيش حاجة نخاف ولا نحزن عليها نسيبها ورانا\nفقالوا له: وإيه ذنب المساكين دول نقتلهم\nلا طبعا مش هنقدر نعمل كده، هات الاقتراح الثالث\n◇فقال لهم الثالث :\nالنهاردة يوم السبت والمسلمين مطمئنين إننا لن نهجم عليهم يوم السبت، فاحنا هنفتح الحصون ونخرج نقاتلهم كلهم بغتة فميلحقوش يجمعوا نفسهم فنقتلهم\n☆كان من شريعة اليهود إنهم لا يقاتلوا يوم السبت وكان معروف عنهم كده.\nفقالوا له عايزنا نقاتل يوم السبت ونعتدي وربنا يمسخنا قردة وخنازير\n \nلأ طبعا مش هنقدر نعمل كده\nفغضب منهم كعب أسد وقال لهم : والله ما في منكم راجل حازم، مش عارفين تاخدوا أي قرار\nفكده مبقاش قصادهم غير حل واحد وهو إنهم يستسلموا لرسول الله ﷺ وينزلوا على حكمه، لكن قبل ما يعلنوا الاستسلام قالوا خلينا نستشير أبا لُبابة،\nأبو لبابة كان من الصحابة من قبيلة الأوس، وكان من حلفائهم من أيام الجاهلية، يعني في عهود بينهم إنهم يدافعوا عن بعض،\nفأرسلوا لرسول الله ﷺ: أرسل لنا أبا لبابة نستشيره في أمرنا\nفأرسل لهم رسول الله ﷺ أبا لبابة، وأول ما دخل عليهم أبو لبابة الصبيان والنساء راحوا ناحيته وقعدوا يبكوا قصاده،\nيعني عاملين له جو نفسي إن أنت النجدة الوحيدة قصادنا،\nفقلبه رق لهم وصعبوا عليه،\nوالرجال رحبوا به وقالوا له: يا أبا لبابة! نحن مواليك دون الناس كلهم\nفقام كعب بن أسد وقال:\nانت عارف احنا عملنا إيه معاك ومع قومك يوم الحدائق ويوم بُعاث وكل حرب كنتم فيها، وعملنا معاكم الواجب،\n-بيذكره بأيام الجاهلية-\nوانت شايف الحصار اشتد علينا إزاي، ومحمد مش راضي يمشي غير لما نستسلم له وننزل على حكمه،\nهو بس لو مشي احنا هنسيب المدينة ونروح الشام أو نروح خيبر ومش هنشارك أي حد تاني في الهجوم عليه، فإيه رأيك نعمل إيه\nطبعا أبو لبابة في شدة التأثر، الناس دي من خمس سنين بس كانوا حبايبه وبيدخل بيوتهم وفي علاقة وِد بينه وبينهم، فدلوقتي بقوا في موقف صعب زي ده،\nومع ذلك قال لهم أبو لبابة: رسول الله ﷺ مش هيسيبكم، فانزلوا على حكمه\nهو لأنه صحابي مؤمن مش ممكن أبدا هيقترح عليهم بشيء مخالف لكلام رسول الله ﷺ،\nولا هيطلب منهم طلب غير إللي طلبه رسول الله ﷺ مهما كان متأثر بالموقف، \nلكنه وهو بيقول لهم انزلوا على حكمه أمسك رقبته أو أشار إلى رقبته، يعني بيقول لهم إن حكم رسول الله ﷺ فيكم هيكون الذبح، القتل يعني،\n☆طب وهو عرف منين إن حكم رسول الله ﷺ هيكون الذبح ورسول الله ﷺ مقلش أي حاجة للصحابة\nالفعل إللي بنو قريظة فعلوه من الغدر والخيانة وتعريض المسلمين كلهم للقتل والذبح كان من نتيجته الطبيعية البديهية إنهم يُقتلوا، \nزي كده لما واحد يعمل خطأ متعمد بيبقى متوقع إن حد هيعاتبه أو يعاقبه بسبب الخطأ ده، \nفكان واضح جدا إن النتيجة الطبيعية للغدر ده هو القتل،\nوهنا أبو لبابة عرف إنه وقع في الذنب\nأفشى سر رسول الله ﷺ\nوبدأ يؤنب نفسه على ما فعله مع أنه لم يره أحد من الصحابة، ورسول الله ﷺ  لا يعلم الغيب، \nفندم أبو لبابة واسترجع، فقال له كعب: مالك يا أبا لبابة\nفقال: خنتُ الله ورسوله\nفنـزل من عندهم ولحيته مبتلة بالدموع من لحظتها، والمسلمين مستنيينه يرجع لهم، ومشي من طريق تاني من وراء الحصن ،مقدرش يواجه النبي ﷺ،\nورجع للمسجد وربط نفسه في عامود من عواميد المسجد،\nوصل الخبر لرسول الله ﷺ فقال :\nدعوه حتى يُحدث الله فيه ما يشاء؛ لأنه هو الذي ربط نفسه\nيعني لو كان جاءني لاستغفرت له، فمادام لم يأتني وذهب، فدعوه  فأنزل الله فيه:\n\"وَلَوْ أَنَّهُمْ إِذْ ظَلَمُوا أَنْفُسَهُمْ جَاءُوكَ فَاسْتَغْفَرُوا اللَّهَ وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ لَوَجَدُوا اللَّهَ تَوَّاباً رَحِيماً\"\nبنو قريظة عرفوا خلاص إن القتل مستنيهم، هم عارفين إن الجريمة إللي عملوها كبيرة جدا وعارفين إنهم كانوا خنجر مسموم في ظهر رسول الله ﷺ والصحابة،\nلكن هم مرعوبين من رسول الله ﷺ ومفيش حل تاني، قصادهم فنزلوا على حكم رسول الله ﷺ\nفاكرين بني قينقاع لما قتلوا المسلم ورسول الله ﷺ حاصرهم وكان حكمه فيهم القتل، لكن عبد الله بن أبي بن سلول جاءه واستنقذهم منه، وقال له أحسن لحلفائي،\nعبد الله بن أبي بن سلول كان من الخزرج، فالأوس هنا افتكروا الموقف ده وهم حلفاء لبني قريظة،\nفقالوا خلاص احنا كمان نستشفع عند رسول الله ﷺ ويطلق لنا بني قريظة زي ما حصل مع الخزرج،\nفراحوا لرسول الله ﷺ وقالوا له:\nيا رسول الله! أحسن إلى حلفائنا كما أحسنت إلى حلفاء إخواننا الخزرج\nطبعا الموقف خطير، وأي قرار غير مدروس ممكن يعمل فتنة بين المسلمين\nرسول الله ﷺ قال لهم بحكمته:\nترضوا إن إللي يحكم فيهم واحد منكم انتم؟\nفقالوا : مَن يا رسول الله\nقال : يحكم فيهم سعد بن معاذ\nفقالوا: سعد! رضينا طبعا، ده هو سيدنا ومصلحتنا من مصلحته\nفي الوقت ده كان سعد بن معاذ رضي الله عنه كان موجود في خيمة كان رسول الله ﷺ أمر إنها تتعمل له وتكون قريبة منه عشان يقدر يزوره كل شوية لأنه كان مريض بسبب السهم إللي أُصيب به في الخندق والدم مكنش بيقف فكوَى رسول الله ﷺ الجرح، فورم الجرح فكواه مرة ثانية كنوع من العلاج، فكان يُطبَّب رضي الله عنه في الخيمة،\nفأرسلوا في طلبه فجاء راكب على حمار، فكان كل إللي يقابله من قومه الأوس يقولوا له:\nيا سعد أحسن إلى حلفائنا، رسول الله ﷺ حكّمك انت فأحسن فيهم\nفكان سعد يقول: قد آن لسعد ألّا تاخذه في الله لومةَ لائم\nيعني أنا كل همي إني أُرضي الله رب العالمين وميهمش أي حاجة تانية، فلما قومه سمعوه بيقول كده عرفوا إنه هيحكم في بني قريظة حكم شديد\nوصل سعد لمكان رسول الله ﷺ وكان الصحابة معاه فقال لهم: قوموا إلى سيدكم!\n فقام الصحابة لسعد بن معاذ رضي الله عنه وأنزلوه من فوق الحمار، وقالوا: \nيا سعد! إن هؤلاء القوم قد نزلوا على حكمك.\nفقال سعد: وحكمي هيتنفذ عليهم؟ قالوا: نعم\nقال: وعلى المسلمين؟ قالوا: نعم،\nقال: وعلى مَن ها هنا؟ وأعرض بوجهه رضي الله عنه ، وأشار ناحية رسول الله ﷺ،\nهو بيتأدب مع رسول الله ﷺ فمش عايز يقول وحكمي نافذ على رسول الله ﷺ، \n فقال له ﷺ: نعم، وعَلَيّ! يعني حكمك هينفذ عليّ\nقال سعد:\nفإني أحكم فيهم أن يُقتل الرجال وتُسبى النساء والذرية وتُقسّم الأموال\nفقال له رسول الله ﷺ: الله أكبر !لقد حكمتَ فيهم بحكم الله من فوق سبع سماوات\nفحفر رسول الله ﷺ الخنادق في سوق المدينة وجعل الصحابة يأتون بالرجال البالغين مجموعة مجموعة يقتلهم في الخنادق،\nواليهود قاعدين مش عارفين إيه إللي بيحصل، سألوا سيدهم كعب بن أسد، يا ترى محمد هيعمل فينا إيه\nفقال لهم كعب: أفِي كل موطنٍ لا تعقلون\nيعني هو انتم معندكوش عقل خالص تفكروا به، \nانتم مش شايفين إنهم بياخدوا مجموعة مجموعة ومحدش منهم بيرجع، واضح إننا هنتقتل كلنا\nفكان رسول الله ﷺ يقتل كل من أَنبت الشعر على العانة، يعني كل مَن بلغ، وده دليل إن البلوغ بيكون بإنبات الشعر الخشن على العانة،\nوواحد من الصحابة كان من سَبْي بني قريظة وهو صغير بيقول إنهم كشفوا عن عانته 《العورة المُغلّظة》فوجوده لم يُنبت الشعر فتركوه ولم يقتلوه.\n☆ركزوا عشان احنا كنا عارفين إن البنت بتبلغ بالحيض والولد بالاحتلام، لكن علامات البلوغ هي :\n إما《 الاحتلام》 أو 《نبات الشعر الخشن حول العانة》، أو 《بلوغ خمس عشرة سنة》، أو 《الحيض》 بالنسبة للأنثى،\nفإذا حصل للولد أو للبنت أي علامة واحدة من علامات البلوغ بقى واجب الإتيان بجميع الواجبات واجتناب جميع المحرمات،\nخلاص بقى في صحيفة سيئات،\nيعني يا جماعة لو البنت ظهر عندها شعر العانة الخشن حتى لو عمرها تسع سنين أو عشرة ولسه الحيض مجاش يبقى البنت بلغت وبقى حكمها زي حكم المرأة الكبيرة،\nتجب عليها الصلاة والصيام والحجاب ومتسلمش على رجال  وتجب عليها كل أفعال الإسلام،\nفخدوا بالكم وعلموا بناتكم وفهموهم \nوطبعا الكلام للولد هو كمان، مادام أنبت الشعر الخشن حول العانة يبقى خلاص بقى بالغ ومينفعش يدخل على النساء ولا يقعد معاهم وتجب عليه واجبات الإسلام ونواهيه،\nابدأوا في تعليم عيالكم من وهم صغيرين شرائع الإسلام عشان على ما ييجي سن البلوغ يبقوا مستعدين\nقُتل من اليهود أربعمائة رجل وفي رواية كانوا سبعمائة \nوقُتل معهم حُيي بن أخطب إللي جمع الأحزاب وأقنع بني قريظة بنقض العهد، \nوكان وعد كعب بن أسد وقال له: لو رجعت غطفان وقريش فسأدخل معكم في الحصن، ومش هسيبك، ودخل فعلا معاهم الحصن ولما قُدِّم للقتل قال لرسول الله ﷺ وهو في حالة القتل:\n والله ما لُمت نفسي في معاداتك، ولكن مَن يُغالب الله يُغلب\nيعني هو عارف إنه بيحارب رب العالمين وبيعترف بكده،\nطيب مش يسلم بقى ويرجع بعد ما شاف الآيات البينات على صدق رسول الله ﷺ\nلأ، الكِبر عماه عن اتباع الحق زي ما عمى إبليس قبل كده، وزي ما عمى قوم نوح،\nوزي ما عمى غيرهم وغيرهم على مر التاريخ، وأهه بيدفع ثمن كبره وقُتل على الكفر وهو خالد مخلد في نار جهنم ، يعني لا كسب دنيا ولا كسب آخرة\nكان في واحد اسمه عمرو من بني قريظة لم يُقتل لأنه كان مسافر وخارج الحصن وقت الغدر،\nفكان واضح جدا إن القتل مكنش انتقاما من اليهود وخلاص،\nالقتل كان بسبب الغدر ونقض العهد أما إللي لم يغدر لم يُقتل،\nوطبعا محدش يفكر إن كان في تجاوز في قتل بني قريظة، أو إنهم اتظلموا أو ...أو...\nانتم متخيلين إنه لولا رحمة ربنا كان إللي هيبقى قاعدين بيُقتلوا دلوقتي هم الصحابة ورسول الله ﷺ\nبنو قريظة كانوا هيعملوا كده في المسلمين، \nومكنش هيبقى الرجال فقط ده كانوا هيقتلوا حتى الأطفال والنساء، \nيا جماعة شريعة الإسلام هي الشريعة الوحيدة إللي بتنهى عن قتل النساء والأطفال والشيوخ والرهبان وتنهى عن قطع الشجر وحرق البيوت وعن التمثيل بجثث القتلى،\nأنا مليش دعوة باللي بعض المُنتسبين للإسلام بيعملوه باسم الإسلام دول ربنا هيحاسبهم،\nلكن تعالوا شوفوا غير المسلمين بيعملوا إيه لما يتمكنوا من المسلمين، قتل واغتصاب وتعذيب وحرق وتمثيل بالجثث،\nومش هقول لكم اقرأوا التاريخ عشان تعرفوا،\nلكن شوفوا في واقعنا المعاصر إللي على غير ملة الإسلام بيعملوا إيه في المسلمين،\nشوفوا اليهود نفسهم بيعملوا إيه دلوقتي مش في المسلمين البالغين، شوفوهم بيعملوا إيه في الأطفال، وما محمد الدّرة وإيمان حجو وغيرهم وغيرهم عنا ببعيد،\nفيهود بني قريظة كانوا هيذبحوا كل أهل المدينة، فالجزاء من جنس العمل،\n\" وَلا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ \"\nوهم لو كان عندهم ذرة ندم، كانوا على الأقل تظاهروا بالإسلام لما كعب بن أسد عرض عليهم عشان يحفظوا دماءهم وأموالهم ونساءهم، لكن دول فضلوا لحد آخر لحظة معاندين مستكبرين،\nولو تركهم رسول الله ﷺ لعادوا مرة ثانية وثالثة لحرب المسلمين وقتالهم\nيا ترى إيه إللي حصل لسعد بن معاذ بعد كده، وإيه إللي حصل لأبي لبابة؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 121, "l": "الجزء 95 | احداث السنه الخامسه من الهجره | واهتز لموته عرش الرحمن | وضمة القبر", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة_والتسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#واهتز_لموته_عرش_الرحمن\n#ضمة_القبر\nاتكلمنا المرة إللي فاتت عن حُكم سعد بن معاذ في بني قريظة وإللي وافَقَ فيه حُكم الله تعالى،\nبعد مقتل بني قريظة وعودة المسلمين إلى المدينة بكم يوم استجاب الله لدعوة سعد بن معاذ،\nسعد كان دعا إن ربنا لا يَقبض روحه لو كان لسه في قتال تاني لرسول الله ﷺ ضد قريش،\nلكن لو مفيش قتال تاني يجعل موته بسبب جرحه فيكون في منازل الشهداء ولكن بعد ما يرتاح إنه انتقم من بني قريظة إللي خانوا العهد،\nانفجر جرحه والجرح قعد ينزف لحد ما مات سعد بن معاذ  شهيدا رضي الله عنه، \nجاء جبريل عليه السلام لرسول الله ﷺ بعد موت سعد وقال له:\nمن هذا العبد الصالح الذي مات ؛ فُتحت له أبواب السماء ، وتحرك له العرش ؟\nفخرج رسول الله ﷺ عشان يشوف مين إللي مات فعرف إنه سعد بن معاذ، ووصل لبيته لقى أمه بتبكيه فقال رسول الله ﷺ: كلُّ نائحةٍ تكذبُ إلا أمَّ سعد\nيعني كل امرأة لما يموت لها ميت وتقعد تتكلم عنه بتقول كلام غير صحيح يعني بتقعد توصفه بصفات كويسة مكنتش فيه بسبب تأثرها بموته، إلا أم سعد فكل صفة بتذكرها عن سعد بن معاذ صفة حقيقية فيه،\nخرج به رسول الله ﷺ مع الصحابه يحملوه، فلقى الصحابة إن جنازته خفيفة مع إن سعد كان رجل طويل وضخم،\nوحتى المنافقين قالوا باستهزاء: ما أخف جنازته\nعشان يعني حكم في بني قريظة بالذبح فده بقى عقابه،\nفقال لهم رسول الله ﷺ : حملته معكم الملائكة، ونزل يُشيّعه سبعون ألف مَلك منزلوش إلى الأرض قبل كده، واهتز لموته عرش الرحمن \nأخذوا سعد بن معاذ رضي الله عنه للبقيع عشان يدفنوه، وبعد ما دفنوه قال رسول الله ﷺ: \nإن للقبر ضغطة يعني ضمة إذا نجا منها أحد كان نجا منها سعد بن معاذ\n◇عندنا هنا نقطتين محتاجين توضيح،\nالأولى: يعني إيه اهتز عرش الرحمن لموت سعد بن معاذ ، والثانية موضوع ضمة القبر،\n☆النقطة الأولى: اهتزاز العرش :\nالعرش اهتز فرحا وشوقا للقاء سعد بن معاذ، فالعرش خَلْق من خلق الله لو عايز يهتز هيهتز بمشيئة الله،\nوربنا جعل فيه شعور لحب سعد ، زي ما جعل في جبل أُحد شعور الحب لرسول الله ﷺ، وقال عنه رسول الله ﷺ: أُحدٌ جبل يحبنا ونحبه،\nوكمان زي ما ربنا جعل الجبال تسبح مع داود زي ما شرحنا في قصص الأنبياء قبل كده، وده كان أحد أقوال العلماء،\nالقول الثاني: إن الاهتزاز كان من فرح الله نفسه ومحبته لقدوم روح سعد رضي الله عنه،\nوفي الحديث أن مَن أحبّ لقاء الله أحبّ الله لقائه.\n☆النقطة الثانية : ضمة القبر:\nكل بشر هيدخل القبر سواء كبير أو صغير مسلم أو كافر صالح أو فاسق فالقبر هيضمه ضمة،\nوهي أول حاجة بتحصل للميت في قبره حتى قبل سؤال الملكين، لكن الضمة دي بتختلف من شخص للتاني وللعلماء فيها قولين:\n◇الأول :\n لو كان الميت مؤمن صالح فالقبر يضمه ويشتد عليه لكن الضمة دي لا تطول، بتخلص بسرعة ولايطول عليه العذاب وهي من كفارات الذنوب،\n أما الكافر والفاسق فالضمة بتكون شديدة جدا عليه وبيبقى وقتها أطول بحسب ذنوبه ومعاصيه،\nوسبب الضغط ده إنه مفيش أي إنسان إلا وعمل ذنب فهتحصل له الضغطة جزاء للذنب ثم تدركه رحمة الله.\n◇القول الثاني :\nإن القبر يضم المؤمن الصالح ولكنها ضمة رفق وحنان مفيهاش أي ألم أو أذى،\nأما المسلم العاصي إللي مات من غير توبة أو الكافر فبتشتد عليه الضمة وتكون ضمة فيها سَخط بحسب كثرة ذنوبهم وسوء أعمالهم، \nزي الأم إللي ابنها بيكون غايب عنها ورجع وهي راضية عنه فتضمه بقوة لكن بحب ورفق، بعكس الأم إللي بتكون ساخطة على ابنها فبتضمه بقوة وغضب.\nوالراجح هو القول الأول لأن ظاهر السنة بيدل على كده، وإن مفيش حد من المؤمنين هينجو من الضمة دي، \nوهي لها ألم لكن ألمها يتفاوت بين الناس كل واحد بحسب عمله وحاله،\nوشيخ الإسلام ابن تيمية رحمه الله قال إن إللي بيحصل في القبر من ضمة القبر والفتنة بسؤال الملكين والخوف من الأمور إللي بتكفر الذنوب،\nفنسأل الله تعالى أن يهون علينا ضغطة القبر \nطبعا الكلام هنا عن ضمة القبر هيوصلنا لسؤالين مهمين \nهل ضمة القبر تشمل الأنبياء، وهل الأطفال الغير بالغين تشملهم ضمة القبر وسؤال الملكين ولّا لأ\n☆أولا: هل ضمة القبر تشمل الأنبياء\nمفيش أي نص ثابت من القرآن أو السنة يدل على إن الأنبياء بيحصل لهم ضمة القبر أو لأ، \nلكن كثير من العلماء على حسب اجتهادهم بيقولوا الأنبياء مش بيحصل لهم ضمة القبر لأن ضمة القبر بتتفاوت شدتها على الميت بحسب ذنوبه،\nوالأنبياء معصومين من كبائر الذنوب ومعصومين من الإقرار على الصغائر زي ما شفنا في قصة يونس وآدم عليهما السلام فالبالتالي ملهمش ذنوب فلا يحصل لهم ضمة القبر ولا حتى سؤال الملكين.\n☆ثانيا : هل الأطفال غير البالغين تشملهم ضمة القبر\nالأطفال كمان تشملهم ضمة القبر، والدليل في قول رسول الله ﷺ عن صبي صغير مات:\n\"لَوْ أَفْلَتَ أَحَدٌ مِنْ ضَمَّةِ القَبْرِ لأَفْلَتَ هَذَا الصَبِيُّ\"\nلكن زي ما قلنا الضغطة بتكون سريعة على المؤمن أو إللي معندوش ذنوب زي الأطفال كده.\n◇أما بالنسبة لسؤال الملكين للأطفال، ففي علماء قالوا:\n إنهم بيتسألوا وإن ربنا سبحانه يُكمِّل لهم عقولَهم ويُلهمهم الجواب عن إللي بيتسألوا عنه وتبقى منزلتهم على حسب جوابهم،\n وده قول شيخ الإسلام ابن تيمية وأنا شخصيا مقتنعة بالرأي ده أكثر \n◇فريق تاني من العلماء قالوا:\nالسؤال بيكون للي يعرف الرسول ومَن أرسله\n فيُسأَل هل آمن بالرسول وأطاعَه ولّا لأ؟ \nلكن الطفلُ إللي مش بيعرف يميّز أزاي هيتسأل : ما كنتَ تقولُ في هذا الرجلِ الذي بُعِثَ فيكم \nولو ربنا كمّل له عقله في القبر فمش هيتسأل عن حاجة معرفهاش ولا له أي علم بها وبالتالي مفيش فائدة من السؤال \nوالكلام عن سؤال الملكين هيدخلنا لسؤال تاني\nسؤال الملكين خاص بأمتنا احنا بس، أمة الإسلام يعني، ولّا عام لجميع الأمم\nأنا هقول لكم القول الراجح في الموضوع وإللي بيدل عليه ظاهر آيات القرآن والأحاديث النبوية ،\nالقول الراجح إن سؤال الملكين عام لأمة الإسلام وكل الأمم السابقة،\nكل أمة مع النبي بتاعها، فيتسألوا من ربك، وما دينك ، وما تقول في هذا الرجل الذي بُعث فيكم،\nفالمؤمنين المُصَدقين في كل أمة هيجاوبوا الإجابة الصحيحة، أما الكفرة والفجرة فمش هيجاوبوا ويُعذبوا في قبورهم لحد يوم القيامة وعذاب الآخرة أشد\n☆طيب وأهل الفترة إللي موصلهمش أي رسالة ولا يعرفوا أي دين وربنا هيمتحنهم يوم القيامة، دول نظامهم إيه في القبر\nباختصار : أهل العلم قالوا إنهم هيتسألوا في القبر وهتكون إجابتهم على حسب مآلهم يوم القيامة، \nيعني إللي ربنا هيختبره يوم القيامة بعنق النار زي ما شرحنا في الجزء السادس ويسمع كلام ربنا هو ده إللي هيجاوب على الملكين في القبر، \nأما إللي هيعصي الله في امتحان يوم القيامة فمش هيعرف يجاوب على سؤال الملكين في القبر.\n♡\nنرجع لرسول الله ﷺ والصحابة بعد موت سعد بن معاذ، \nتأثر رسول الله ﷺ والصحابة لموت سيد الأوس سعد، هم عاشوا معاه ست سنين فقط بعد إسلامه لكن الست سنين دول كانت كلها مواقف مُشرّفة في نصرة الإسلام،\nمن أول يوم إسلامه ووقوفه قصاد قومه كلهم ودعوتهم جميعا للإسلام وأسلموا كلهم ساعتها بإسلام سعد،\nوحتى آخر موقف في حياته وهو حكمه على بني قريظة بحكم الله،\nالعبرة مش الإنسان عاش كم سنة، العبرة الإنسان كان تأثيره إيه في السنين إللي عاشها، \nشوفوا احنا مسلمين بقالنا أد إيه عايشين، هل عملنا شيء لما نموت نتركه أثرا وراءنا؟\nالسماء والأرض هتبكي لفقدنا؟\nأيوة السماء والأرض تبكي لموت الصالحين ولا تتأسف على موت الكافرين والطغاة،\n\" فَمَا بَكَتْ عَلَيْهِمُ السَّمَاء وَالْأَرْضُ وَمَا كَانُوا مُنظَرِينَ\" \nالأرض تتأسف لفقد المؤمن إللي كان بيمشي عليها، كان\nيصلي عليها، ويذهب للدعوة إلى الله فوقها، ويمشي ليصِل رحمه، ويغيث الملهوف، ويعمل المعروف، ويزيل المنكر، وغيرها من الطاعات،\nخليكم فاكرين: العبرة مش في عمر الإنسان أد إيه على أد ما العبرة في هو قدّم إيه في عمره ده \nفي الوقت ده كان أبو لبابة رابط نفسه في سارية المسجد  عمود يعني من عواميد المسجد، \nوكان لا يأكل ولا يشرب، كان يقوم بس للصلاة ويرجع تاني يربط نفسه وقال: أنا هفضل كده لحد ما أموت أو يتوب الله عليّ\nفاستمر كده حوالي سبعة أيام، لدرجة إن محدش بقى يسمع له صوت من التعب الشديد إللي وصل له،\nورسول الله ﷺ يعدي عليه الصبح وبالليل ويبص عليه مش في إيده يعمل له حاجة\nفي ليلة من الليالي في وقت السَّحر كان رسول الله ﷺ عند أم سلمة فسمعته يضحك، فسألته : بتضحك على إيه يا رسول الله = أضحك الله سنك = ؟\nفقال رسول الله ﷺ: \nلقد تاب الله على أبي لبابة\nفقالت له: أروح ابشره يا رسول الله؟\nفقال لها : لو انتِ عايزة روحي بشريه!\nفوقفت على باب حجرتها وكان الباب بيتفتح على المسجد على طول، فقالت: \nيا أبا لبابة! أبشر لقد تاب الله عليك\nفالناس إللي كانوا في المسجد ثاروا عشان يفكوه ويُطلِقوه،\nفقال: لا والله حتى يكون رسول الله ﷺ هو إللي يُطلقني بيده\nفخرج بعدها رسول الله ﷺ لصلاة الصبح فأطلقه.\nربنا تاب عليه لأنه كان صادق في التوبة، كان فعلا ندمان، هو كان يقدر يخبي إللي عمله عن رسول الله ﷺ، ومكنش حد هيعرف وكان هيقول لليهود محدش فيكم يجيب سيرة إني قلت لكم حاجة،\nزي ما ناس كتير بتعمل دلوقتي، يعملوا الغلط ويبقوا حريصين إن محدش من البشر يعرف حاجة ويستمروا في الغلط، لكن ناسيين إن في حد بيراقبهم وبيراقب أفعالهم كلها،\nوهو ده إللي فهمه أبو لبابة، \nمهما خبى ومهما دارى فهو عارف كويس إنه ميقدرش يخبي أي حاجة عن ربنا إللي يعلم السر وأخفى،\nهو أه وقع في الذنب لكنه أتبع الذنب ده بتوبة صادقة، وكانت النتيجة إن ربنا تاب عليه، \nبسبب الذنب ده تولّد في قلب أبي لبابة الخوف والحياء والمهابة والتعظيم لله سبحانه وتعالى ،\nوعرف معاني وعبادات قلبية مكنش هيعرفها غير لما يمر بالموقف ده، فمش دايما وقوع الإنسان في الذنب بيبقى حاجة وحشة،\nساعات الإنسان بيقع في ذنب ويكون الذنب ده سبب في دخوله للجنة تخيلوا\nيعني من حكمة ربنا في تقدير الذنب على العبد وإنه لا يعصمه منه إنه يُنسيه رؤية عمله في طاعة الله،\nمش ساعات بتحصل معانا إننا نكون مطيعين جدا لربنا فترة وفجأة كده نقع في ذنب معين،\nزي مثلا الواحد في رمضان بيبقى جايب آخره في العبادة وبكاء وخشوع وقراءة قرآن وفجأة بعد رمضان مش بس ييجيله فتور ده ممكن كمان يقع في معاصي مكنش ممكن يتخيلها، \nوده لأن ربنا يريد إنه يعلّم العبد انكسار القلب والخشية وينزع من قلبه الرياء والعجب والتكبر،\nيعني ممكن الإنسان يشوف طاعته وإنه عمل حاجة كبيرة،\nفربنا من رحمته يُقدّر عليه الذنب عشان يحتقر عمله وميشفش قصاده غير ذنبه فقط ويخاف من ربنا ومن عقابه ويبقى دايما مكسوف من ربنا وإزاي هيقابله بالذنب ده،\nويفضل في الإنكسار والخشية دي ويفضل يعمل أعمال عشان يعوّض الذنب ده،\nوربنا بيقول في الحديث القدسي:\n\"وَعِزَّتِي لَا أَجْمَعُ لِعَبْدِي أَمْنَيْنِ وَلَا خَوْفَيْنِ : \nإِنْ هُوَ أَمِنَنِي فِي الدُّنْيَا أَخَفْتُهُ يَوْمَ أَجْمَعُ فِيهِ عِبَادِي، وَإِنْ هُوَ خَافَنِي فِي الدُّنْيَا أَمَّنْتُهُ يَوْمَ أَجْمَعُ فِيهِ عِبَادِي\"\nيعني إللي بيخاف من ربنا في الدنيا هيبقى آمن يوم القيامة، أما إللي بيعمل الذنوب وهو مش فارق معاه حاجة وعادي يا جماعة بقى ماهو ربنا غفور رحيم\nده إللي ربنا هيخوفه يوم القيامة فانتبهوا\nفباختصار كده ربنا ممكن يقدّر على العبد فعل الذنب عشان الخير إللي هيحصل للعبد بعد كده من توبة وخوف وانكسار وترك العُجب والإقبال على الله ويكون كل ده سبب لدخوله الجنة،\nوده إللي حصل مع أبي لبابة وبيحصل مع المؤمنين الأتقياء على مر الزمن \nدلوقتي زعيم الأوس سعد بن معاذ مات فلازم واحد تاني يمسك بداله، فأصبح زعيمهم بعد سعد هو أسيد بن حُضير، إللي كان سبب في إسلام سعد بن معاذ لو تفتكروا قصته\nوسعد يبقى زوج عمته، \nوكان أُسيد من العقلاء أصحاب الرأي، ومكانته بين الناس زي مكانة سعد بن معاذ كده، وكان له صوت جميل وهو يقرأ القرآن،\nحتى إنه مرة كان بيقرأ القرآن بالليل في مِربَده، حاجة زي الاسطبل كده كان فيها فرسه، وكان ابنه يحيى صغير قاعد جنب الفرس،\nفكان بيقرأ القرآن فالفرس تحركت حركة شديدة فتوقف عن القراءة فسكنت الفرس،\nفبدأ يقرأ مرة ثانية فالفرس اتحركت بشدة تاني، فخاف أحسن تدوس على ابنه يحيى فقام يشوف ليه الفرس بتتحرك كده ويطمن على ابنه،\n فلقى فوق رأسه زي غمامة كده فيها زي أضواء ومصابيح، الغمامة دي فضلت ترتفع في السماء لحد ما اختفت،\nالصبح راح أسيد بن حضير لرسول الله ﷺ وقال له:\nامبارح وأنا بقرأ القرآن في مربدي يا رسول الله لقيت الفرس اتحركت حركة شديدة\nفقال له رسول الله ﷺ:\nاقرأ ابن حُضير!\nيعني رسول الله ﷺ بيشجعه على الاستمرار في القراءة و إنه ميقطعهاش، لأن القراءة سبب لنزول الملائكة والبركة وذكر العبد عند الله تعالى،\nفقال له أُسيد: فقرأت تاني فتحركت بشدة مرة تانية\nفقال له رسول الله ﷺ:\nاقرأ ابن حضير!\nفقال له أسيد: مكملتش وقمت أشوف إيه إللي بيخلي الفرس تتحرك كده وخفت على يحيى من إنها تدوسه بحوافرها\nفلما قمت شفت سحابة فيها مثل المصابيح مضيئة منيرة، وفضلت تطلع فوق في الجو لحد ماختفت تماما ومبقتش شايفها،\nقال له رسول الله ﷺ:\nدي الملائكة جاءت تستمع إليك، ولو استمريت في القراءة لحد الفجر كان الناس شافوهم على هيئتهم النورانية دي\nغزوة الأحزاب خلصت وخلاص انتهينا من بني قريظة، لكن في واحد من اليهود إللي خرجوا مع حُيَي بن أخطب عشان يجمعوا المشركين ضد رسول الله ﷺ في الأحزاب عرف يهرب ويروح القلعة بتاعته في خيبر، \nوقلنا إنه كان فاحش الثراء وهو إللي كان بيصرف على خطة تجميع الأحزاب، هل يا ترى رسول الله ﷺ هيسيبه كده يكمل في عداوته ويستعمل أمواله ضد المسلمين؟\nولّا هيكون له تصرف تاني معاه\nده إللي هنعرفه الجزء الجاي إن شاء الله \n☆احنا قلنا اسم الرجل اليهودي ده في الجزء التاسع والثمانون، مين يقدر يفتكر اسمه\n♡"}, {"n": 122, "l": "الجزء 96 | احداث السنه الخامسة من الهجرة | مقتل ابو رفع اليهودي", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة_والتسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#مقتل_أبو_رفع_اليهودي\nشوفنا في الأجزاء الأخيرة إللي حصل مع الأحزاب ومع بني قريظة، وقَتْل حُيَي بن أخطب إللي كان حزّب الأحزاب ضد رسول الله ﷺ، \nمينفعش رسول الله ﷺ يسيب القبائل إللي اشتركت في الهجوم على المدينة كده من غير ما يكون له رد فعل عشان القبائل تعرف إن انتهاك حرمات الأمة الإسلامية مش هيعدي بدون عقاب\nفبدأ رسول الله ﷺ يبعت السرايا المختلفة لتأديب القبائل دي عشان يعرفهم قوة المسلمين،\nوكانت حملات عسكرية مكثّفة بمُعدّل حملة عسكرية كل عشرين يوم تقريبا\n☆ممكن حد يسأل ويقول مش المفروض المسلمين يريّحوا شوية بعد التعب إللي شافوه في الكم شهر إللي فاتوا\nأو على الأقل ميقلّبُوش الناس عليهم\nشوفوا يا جماعة، \nالأمة التي لا تجاهد تُصاب بالذل\nوده كلام رسول الله ﷺ، فضعف وذل المسلمين مش بس هيؤدي للتهديد المستمر على دولة الإسلام من أعدائها،\nده هيؤدي لفقد الثقة في الدين الإسلامي نفسه،\nالناس هتقول: \nلو كان الدين ده حق كان أصحابه كافحوا ودافعوا عنه\nلو الدين ده عظيم كان فرض نفسه على الآخرين وانتشر\nبسبب الوضع الصعب للمسلمين وتفريط أكثرهم في الدين؛ غير المسلمين هينفروا من الإسلام لعدم ثقتهم في المسلمين،\nوده إللي رسول الله ﷺ طبعا مش عايزه يحصل، \nهو عايز تكون صورة الأمة الإسلامية مَهِيبة وسط الجزيرة العربية ولها مكانتها الخاصة\nوده إللي الصحابة نفسهم كانوا فاهمينه ومنهم الأنصار:\nالأَوْس والخَزْرج،\nاحنا عارفين إن كان في حروب كثيرة بين الأَوْس والخزرج  قبل الإسلام، أما بعد الإسلام فهم استغلوا الحمَيّة إللي كانت بينهم دي لنصرة الله ورسوله،\nفكانوا دايما بيتفاخروا في مجالسهم بمميزاتهم وبمين له ميزة أكثر من التاني،\nفكان الأَوس يقولون : \nمنّا غِسّيل الملائكة حنظلة بن الراهب، ومنّا من اهتز له عرش الرحمن يوم مات سعد بن معاذ،\nومنا إللي الدبابير حمت جسده وهو عاصم بن ثابت ومنا من شهادته بشهادة رجلين وهو خُزيْمة بن ثابت\n《هقول لكم قصته بعد شوية》\nفكان الخزرج يردون عليهم ويقولوا:\nاحنا بقى منا أربعة لم يجمع القرآن أحد غيرهم: \nزيد بن ثابت، وأبو زيد وأُبَيّ بن كعب ومعاذ بن جبل\nفكان ده حالهم على طول \nفلما الأوس تقربت إلى الله ورسوله بقتل كعب بن الأشرف لو تفتكروا قصته في الجزء الخامس والستين،\nإللي رسول الله ﷺ قال عنه: مَن لكعب بن الأشرف فإنه آذى الله ورسوله فتطوع مجموعة من الأوس وقتلوه،\nهنا الخزرج قالوا :\nهم الأوس مفكرين إنهم هيسبقونا بالفضل\nفقعدوا يشوفوا مين ألَدّ أعداء النبي ﷺ \nفملقوش غير أبو رافع سلّام بن أبِي الحُقَيق التاجر الشهير فاحش الثراء،\nإللي كان من زعماء بني النّضير ومن أثرياء اليهود، وكان من الذين حزّبوا الأحزاب ضد رسول الله ﷺ مع حُيي بن أخطب إللي قُتل مع يهود بني قريظة،\nأبو رافع بعد نهاية الأحزاب رجع لقلعته إللي كانت على أطراف الحجاز داخل حصون خيبر،\nوالصحابة عارفين إن أذيته للمسلمين وعدائه للإسلام مش هيقف وهيشوف أي فرصة ويستغلها عشان يحارب الإسلام مرة ثانية\nفراحت مجموعة من الخزرج لرسول الله ﷺ واستأذنوه إنهم يقتلوا أبو رافع اليهودي،\nفأَذِن لهم رسول الله ﷺ وجعل قائد السرية دي عبد الله بن عَتِيك ،ووصّاهم رسول الله ﷺ وقال:\n\" لا تقتلوا وَليدًا ولا امرأة \"\nودي كانت أول سرية بعد غزوة الأحزاب،\nخرج عبد الله بن عَتيك مع ثلاثة أو أربعة من الصحابة وتوجهوا لقلعة أبو رافع،\nوصلوا للقلعة بعد غروب الشمس وكان في الوقت ده عُمال القلعة راجعين بسَرْحهم، يعني كانوا بيسرحوا بالمواشي طول اليوم فرجعوا بالمواشي للقلعة بعد غروب الشمس،\nفي اللحظة دي عبد الله بن عتيك قال لأصحابه:\nخليكم هنا متتحركوش، أنا هحاول أعمل اي خدعة وأدخل الحصن\n☆سبب ذهاب عبد الله بن عتيك بالذات ومش أي واحد تاني إنه كان له أم من الرضاع في خيبر وكان بيعرف يتكلم اليهودية،\nفلو حصل وحد مسكه هيعرف يلاقي حجة ينجي بيها نفسه\nذهب عبد الله بن عتيك بالقرب من بوابة القلعة وتقنّع بثوبه، يعني غطى وشه ومبقاش باين غير عينه والدنيا خلاص كانت داخلة على الليل وجلس كأنه بيتبول بجانب البوابة،\nفحارس البوابة لما شاف هيئته ظنه واحد من العمال إللي لسه جايين فقال له: \nانت ياللي هناك، لو كنت هتدخل فادخل دلوقتي عشان أنا عايز أقفل الباب\nفراح عبد الله بن عَتِيك داخل للقلعة واستخبى في جنب،\nفبعد ما حارس البوابة البوابة أغلق البوابة علّق المفاتيح على وَتد، خشبة كده بيتعلق عليها المفاتيح،\nفي الوقت ده كان عند أبو رافع جماعة سهرانين بياكلوا ويشربوا الخمر، ما هو زعيم الحصن بقى\nبعد شوية لما الحركة هديت والضيوف إللي عند أبو رافع مشيوا ومبقاش في صوت مسموع، تسلّل عبد الله بن عَتيك وأخذ المفاتيح،\nأغلق على البوّاب باب غرفته من الخارج، وأغلق كل الأبواب إللي كانت تقابله من الخارج، \nعشان محدش يخرج من أي غرفة، أما الباب إللي كان بيدخل منه فكان يغلقه على نفسه من الداخل عشان محدش يفتح عليه الباب ويدخل وراه،\nأبو رافع بقى كان في عَلاَلِيَ له، يعني غرفة فخمة كده في دور عُلوي يُصعد له بسلم خشب،\nفدخل عبد الله بن عتيك لغرفة أبي رافع لقى الدنيا ضلمة كُحل\nومش عارف هو فين بالضبط، ومش معاه حاجة يُضيء بيها الغرفة، يعمل إيه\nراح منادي عليه بصوت عالي\nيا أبا رافع\nفراح رادد عليه أبو رافع وقال له: مين\nعرف عبد الله بن عتيك مكان أبو رافع وتوجه ناحية صوته وضربه ضربة بالسيف لكنها كانت ضربة بسيطة لم تقتله وصرخ أبو رافع يستغيث بحد ينقذه،\nعبد الله بن عتيك راح ماشي من عنده كأنه هرب، ورجع له تاني وغيّر صوته كأنه واحد من الخدم بتوعه جاي يساعده فقال عبد الله بن عتيك لأبي رافع:\nمالك يا أبا رافع\nفقال له أبو رافع:\nلأمك الويْل\n في واحد ضربني بالسيف\nفراح عبد الله بن عتيك ضربه الضربة الثانية\nلكن برده الضربة دي لم تقتله، \nفمشي عبد الله بن عتيك مرة ثانية كأنه هرب ورجع له تاني \nوغير صوته تاني كأنه واحد من الخدم بتوعه جاي يساعده\nفقال عبد الله بن عتيك لأبي رافع:\nمالك يا أبا رافع\nفلقاه مرمي على ظهره على الأرض، فأدخل عبد الله بن عتيك طرف سيفه في أسفل بطن أبي رافع وضغط على السيف لحد ما سمع صوت العظم، فعرف ساعتها إنه كده خلاص قتله واستيقظ أهل البيت\nخرج عبد الله من عنده بسرعة وقعد يفتح الأبواب باب باب لحد ما وصل للسلم الخارجي، \nوكان مفكر إنه خلاص وصل للأرض، فبيحط رجله راح واقع على رجله فانخلعت ركبته وساقه اتكسرت \n☆ عبد الله بن عتيك مقلش: أنا يارب بعمل خدمة للدين تقوم تقدّر عليّ إن رجلي تتكسر، مش المفروض تحفظني بقى، مانا بعمل حاجة ترضيك أهه\nبتحصل ولّا لأ\nلما واحد فينا بيعمل طاعة أو يتقرب إلى الله بأي عمل خير وربنا ابتلاه بعدها على طول بأي ابتلاء، ممكن ييجي في باله الكلام ده ولّا لأ، حتى لو منطقش بيه\nطيب عبد الله بن عتيك كان رد فعله إيه ساعتها، وخصوصا إن الموضوع مش سهل ده كسر رجل، \nده الواحد لما رجله بتتلوى بس شوية مش بيبقى قادر يتحرك\nعبد الله بن عتيك بكل بساطة فك العمامة بتاعته وربط رجله بيها وانطلق لأصحابه يخبرهم باللي حصل، ولا اهتم أصلا بالموضوع\nهو عارف إن طريق ربنا مش مفروش بالورود ولكنه مفروش بالابتلاءات، هو عارف إن الجنة لا يُلقّاها إلا الذين صبروا،\nعشان كده كان كسر رجله بالنسبة له من جُملة الابتلاءات على الطريق \nوصل عبد الله بن عتيك للمكان إللي فيه أصحابه ولما وصل قال لهم:\nيلا بسرعة امشوا من هنا، وروحوا بشروا رسول الله ﷺ فقد قتل الله أبا رافع، أنا هفضل قاعد هنا لحد ما اسمع الناعي ينعي أبا رافع!\n☆عبد الله بن عتيك بيعلمنا معنى جميل جدا هنا\nهو مين إللي خطط ومين إللي رتب ومين إللي دخل الحصن ومين إللي كان خايف يتمسك ومين عمل الحيلة عشان يقتل أبا رافع ومين إللي رجله اتكسرت؟\nمش عبد الله بن عتيك؟\nلكنه هنا بينسب الفضل في كووول ده لله عز وجل، \nفهو بيقول لنا إن الإنسان مش بشطارته يقدر يعمل أي إنجاز، \nلولا توفيق ربنا للعبد مكنش قِدر يتحرك ولا يعمل أي خطوة،\nإذا لم يَكُنْ عَوْنٌ من اللهِ للفَتَى   فأوّلُ ما يَجْنِي عَليهِ اجْتِهادُه\nانطلق الصحابة باتجاه المدينة وانتظر عبد الله بن عتيك يسمع الناعي،\nأول ما صاح الديك طلع النّاعي على سور الحصن وقال:\nأنعي لكم أبا رافع تاجر أهل الحجاز!\nكده بقى إعلان رسمي بموت أبي رافع، فانطلق عبد الله بن عتيك خلف أصحابه ومكنش حاسس بأي ألم نهائي، ربنا رفع عنه الألم\nوتخيلوا إنه كمان لِحق أصحابه إللي كانوا سبقوه في الطريق قبل ما يوصلوا لرسول الله ﷺ \nلما وصلوا لرسول الله ﷺ بشّروه بمقتل أبو رافع فحمد الله، وعرف رسول الله ﷺ إن رجل عبد الله بن عتيك اتكسرت فقال له : ابسط رجلك! يعني افرد رجلك، \nفبسطها فمسح عليها رسول الله ﷺ فرجعت زي ماكانت وكأنها لم تُصب أبدًا \nودي كانت من معجزات رسول الله ﷺ، كَسر زي ده ممكن يقعد على الأقل شهر في الجبس، لكن الله شفاه بمسحة واحدة من يد رسول الله ﷺ \n◇قَتل أبو رافع كان خطوة مهمة جدا لأن ده فيه رسالة تخويف لليهود،\nفقتل واحد في مكانة أبو رافع وثراءه هيخلي أي حد يراجع نفسه قبل ما يفكر بس إنه يشجع الكفار أو يجمعهم أو حتى يموّلهم بالأموال لحرب المسلمين،\nلأن اليهود أحرص الناس على حياة..أي حياة المهم إنه يعيش وخلاص، فدي رسالة واضحة لكل اليهود: \nاحنا وصلنا للقائد والزعيم بتاعكم في وسط حصونكم في غرفة نومه وقتلناه\nفما بالكم باللي أقل منه ممكن نعمل فيه إيه\nفده خلى اليهود مرعوبين من رسول الله ﷺ والمسلمين،\nولو لاحظتم رسول الله ﷺ كان دايما بيركز على قتل قادة الكفر وزعمائه...ليه\nلأن لما القائد إللي مجمع الناس ضد رسول الله ﷺ وضد المسلمين خلاص يموت؛ هينتهي أمر الجيوش كلها وتنكسر شوكة الأعداء، \nزي ما اتكلمنا قبل كده في الجزء الثالث والثمانون عن قصة اغتيال خالد بن سفيان الهذلي إللي كان بيجمع القبائل لحرب رسول الله ﷺ،\nبمجرد اغتياله خلاص تفرق كل التجمعات إللي جمعها\nفكده بقى واضح للكل إن الدولة الإسلامية إللي كانت مُحاصرة لسه من كم يوم مش دولة ضعيفة ولسه هتكبر وشوكتها هتقوى\n☆قبل ما نكمل باقي الأحداث عايزين نعرف مين خُزَيمة بن ثابت إللي شهادته تساوي شهادة رجلين ده\nخُزَيْمَة بن ثابت صحابي من الأنصار من إللي حضروا غزوة بدر، كان مرة في السوق فسمع واحد من الأعراب بيقول  لرسول الله ﷺ: هات لي شهيد يشهد إني بعت لك الفرس\nفخزيمة بن ثابت راح داخل في الحوار على طول كده بدون أي مقدمات وقال للأعرابي: \nأنا أشهد إن رسول الله ﷺ اشترى منك الفرس\nمع إن خزيمة مكنش يعرف حاجة خالص ولا إيه الحوار أصلا\nدلوقتي انتم مش فاهمين الحكاية إيه ولا إيه موضوع الفرس ده صح\nأهه ده بالضبط كان موقف خزيمة بن ثابت مكنش عارف حاجة خالص ومع ذلك شهد لصالح رسول الله ﷺ،\nحتى رسول الله ﷺ استغرب وسأله: انت بتشهد بإيه وانت متعرفش الحوار؟!!\nفرد عليه بكل بساطة ويقين:\nَبتَصْدِيقِك يا رسول الله\nيعني بيقول لرسول الله ﷺ أنا مصدقك في الوحي إللي بيجيلك مش هصدقك في موقف بيع وشراء\nفشهادة خزيمة رضي الله عنه كانت مبنية على تصديق عام لرسول الله ﷺ وده أصل الإيمان برسول الله ﷺ،\nفحتى لو مشافش إللي حصل مع رسول الله ﷺ فهو واثق من صدق رسول الله ﷺ،\nفهنا رسول الله ﷺ جعل شهادة خزيمة بشهادة رجلين،\nيعني ربنا بيقول لنا عن الشهود إنهم على الأقل يكونوا شاهدين،\n\"وَاسْتَشْهِدُوا شَهِيدَيْنِ مِنْ رِجَالِكُمْ\"\nفلو حد احتاج لشهادة شهود لو أخذ خزيمة فقط فهو بيكفي، ودي حاجة خاصة فقط بخزيمة بن ثابت رضي الله عنه\nعايزين نعرف بقى إيه قصة رسول الله ﷺ مع الأعرابي\nرسول الله ﷺ كان في السوق وشاف فرس عجبته مع واحد من الأعراب فاشتراها منه رسول الله ﷺ،\nفقال له رسول الله ﷺ: تعال ورايا ومعاك الفرس عشان أعطيك ثمنها!\nمشى رسول الله ﷺ وأسرع في المشي والأعرابي كان ماشي ببطئ فسبق رسول الله ﷺ الأعرابي،\nفبعض الرجال شافوا الفرس مع الأعرابي فعجبتهم فقعدوا يُساوموه عشان يشتروها منه وهم ميعرفوش إن رسول الله ﷺ كان خلاص اشتراها،\nفالأعرابي زي ما تقولوا طمع، لقى الطلب كتير على الفرس بتاعته فحب يستغل الموقف ويطلع بصفقة من الموضوع\nفنادى على رسول الله ﷺ وقال له:\nانت هتشتري الفرس ده ولّا خلاص أبيعه \nفرسول الله ﷺ لما سمع نداء الأعرابي قال له:\nهو مش انت خلاص بِعْتَ لِي الفرس؟!!\nفالأعرابي قال له: لا والله، مبعتلكش حاجة\nفرسول الله ﷺ قال له: لأ، انت بعتلي فرسك\nفالأعرابي قال له: \nهات لي شهيد يشهد إني بعت لك الفرس\nوهنا تدخل خُزَيمة بن ثابت وشهد لرسول الله ﷺ زي ما قلنا من شوية \n☆ممكن حد يسأل، هو يعني الصحابة مش مصدقين برسول الله ﷺ، اشمعنى خزيمة بس هو إللي قال كده وباقي الصحابة فضلوا واقفين يتفرجوا\nهو الموضوع موضوع فِطْنة مش أكثر، يعني هو انتبه لمعنى غفل عنه باقي الصحابة، مش ساعات بنتحط في مواقف نتسأل سؤال مثلا، أو يحصل موقف منبقاش عارفين نتصرف إزاي فنلاقي حد اتصرف تصرف احنا عارفينه وكان ممكن نعمله بس مجاش على بالنا نعمله أو نرد بالرد بتاعه،\nأهه ده إللي حصل بالضبط هنا، الصحابة اتصدموا من الموقف، \nرسول الله ﷺ واقف قصاد أعرابي بيقول انت بعتني الفرس والأعرابي بيقول له لأ، فحصل لهم اندهاش ومبقوش عارفين يعملوا إيه، \nفلما انتبه خُزيمة للموقف وردّ بفطنته بكلام إللي حواليه عارفينه لكن غفلوا عنها كان جزاؤه إن شهادته تكون بشهادة رجلين\nمثال تاني للتوضيح: \nمرة رسول الله ﷺ كان قاعد مع الصحابة فقال لهم إن في سبعين ألف من أمة الإسلام هيدخلوا الجنة بغير حساب ولا عذاب، فعلى طول انتبه عُكّاشة بن مِحْصن وقال لرسول الله ﷺ: ادعُ الله ان يجعلني منهم يا رسول الله \nفقال له رسول الله ﷺ: أنت منهم\nفلما قام رجل تاني من الصحابة وقال لرسول الله ﷺ ادعُ الله أن يجعلني منهم، قال له رسول الله ﷺ:\nسبقك بها عُكاشة\nفالفطنة والانتباه كانوا سبب في فوز خُزيمة وعكاشة بمنزلة خاصة بهما محدش ينازعهم فيها\nالأحداث الأخيرة إللي فاتت كنا بنتكلم فيها عن الحالة  العسكرية الجهادية للدولة الإسلامية، في وسط الأحداث دي كان في أحداث تانية بتحصل من ناحية الحالة الاجتماعية،\nوالأحداث دي  هيكون لها أثر كبير جدا في المدينة\nيا ترى إيه إللي حصل، ده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
